PathwayData.put("data/reading_writing/units/L03U1.json",{"strand":"reading_writing","level":3,"cefr":"A2a","unit":1,"theme":"Amazing Animals","essential_question":"How do animals survive in their homes?","schema_version":"1.0","core_words":["habitat","desert","ocean","forest","nest","burrow","hunt","hide","protect","claws","feathers","fur","shell","survive"],"recycled_words":["camel","fox","turtle","owl","hot","cold","night","because","so","heading","topic sentence","desert","sand"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L03-U1-LS1","title":"Word Power: Amazing Animals","lesson_type":"vocabulary","objectives":["read, say and use 14 words about animals and their homes and 3 Tier 2 words (adapt, explain, support)","find the meaning of a new word from a definition clue in the same sentence (is, means, or, called, commas and dashes)","sort animals and body parts by habitat and explain how they help animals survive"],"objectives_ar":["قراءة ونطق واستخدام 14 كلمة عن الحيوانات وبيئاتها و3 كلمات أكاديمية (adapt, explain, support).","إيجاد معنى الكلمة الجديدة من دليل التعريف في الجملة نفسها.","تصنيف الحيوانات وأجزاء أجسامها حسب البيئة وشرح كيف تساعدها على البقاء."],"success_criteria":["I can read and use the animal words in sentences.","I can find a definition clue and use it to explain a new word.","I can say how claws, fur, feathers or a shell help an animal."],"success_criteria_ar":["أستطيع قراءة كلمات الحيوانات واستخدامها في جمل.","أستطيع إيجاد دليل التعريف واستخدامه لشرح كلمة جديدة.","أستطيع قول كيف تساعد المخالب أو الفرو أو الريش أو الصدفة الحيوان."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"habitat","pos":"noun","ipa":"/ˈhæbɪtæt/","definition":"the natural home of an animal or plant","arabic":"موطن / بيئة طبيعية","example":"The desert is the camel's habitat.","image_id":"IMG-RW-L03-U1-LS1-V01","audio_id":"AUD-RW-L03-U1-LS1-V01","tier":"core"},{"word":"desert","pos":"noun","ipa":"/ˈdɛzərt/","definition":"a very dry place with little rain and lots of sand or rock","arabic":"صحراء","example":"Few plants grow in the desert.","image_id":"IMG-RW-L03-U1-LS1-V02","audio_id":"AUD-RW-L03-U1-LS1-V02","tier":"core"},{"word":"ocean","pos":"noun","ipa":"/ˈoʊʃən/","definition":"a very big area of salt water","arabic":"محيط","example":"Whales live in the ocean.","image_id":"IMG-RW-L03-U1-LS1-V03","audio_id":"AUD-RW-L03-U1-LS1-V03","tier":"core"},{"word":"forest","pos":"noun","ipa":"/ˈfɔrɪst/","definition":"a large area with many trees","arabic":"غابة","example":"Owls live in the forest.","image_id":"IMG-RW-L03-U1-LS1-V04","audio_id":"AUD-RW-L03-U1-LS1-V04","tier":"core"},{"word":"nest","pos":"noun","ipa":"/nɛst/","definition":"a home that birds build from sticks and grass","arabic":"عُشّ","example":"The bird lays eggs in its nest.","image_id":"IMG-RW-L03-U1-LS1-V05","audio_id":"AUD-RW-L03-U1-LS1-V05","tier":"core"},{"word":"burrow","pos":"noun","ipa":"/ˈbɝroʊ/","definition":"a hole or tunnel in the ground where an animal lives","arabic":"جُحر","example":"The fox sleeps in a burrow.","image_id":"IMG-RW-L03-U1-LS1-V06","audio_id":"AUD-RW-L03-U1-LS1-V06","tier":"core"},{"word":"hunt","pos":"verb","ipa":"/hʌnt/","definition":"to chase and catch other animals for food","arabic":"يصطاد","example":"Owls hunt at night.","image_id":"IMG-RW-L03-U1-LS1-V07","audio_id":"AUD-RW-L03-U1-LS1-V07","tier":"core"},{"word":"hide","pos":"verb","ipa":"/haɪd/","definition":"to go where others cannot see you","arabic":"يختبئ","example":"The lizard hides under a rock.","image_id":"IMG-RW-L03-U1-LS1-V08","audio_id":"AUD-RW-L03-U1-LS1-V08","tier":"core"},{"word":"protect","pos":"verb","ipa":"/prəˈtɛkt/","definition":"to keep safe from danger","arabic":"يحمي","example":"A shell protects the turtle.","image_id":"IMG-RW-L03-U1-LS1-V09","audio_id":"AUD-RW-L03-U1-LS1-V09","tier":"core"},{"word":"claws","pos":"noun","ipa":"/klɔz/","definition":"sharp, curved nails on an animal's feet","arabic":"مخالب","example":"The falcon catches food with its claws.","image_id":"IMG-RW-L03-U1-LS1-V10","audio_id":"AUD-RW-L03-U1-LS1-V10","tier":"core"},{"word":"feathers","pos":"noun","ipa":"/ˈfɛðərz/","definition":"the soft, light things that cover a bird's body","arabic":"ريش","example":"Feathers keep birds warm and help them fly.","image_id":"IMG-RW-L03-U1-LS1-V11","audio_id":"AUD-RW-L03-U1-LS1-V11","tier":"core"},{"word":"fur","pos":"noun","ipa":"/fɝ/","definition":"the thick, soft hair on some animals","arabic":"فرو","example":"The fox has thick fur.","image_id":"IMG-RW-L03-U1-LS1-V12","audio_id":"AUD-RW-L03-U1-LS1-V12","tier":"core"},{"word":"shell","pos":"noun","ipa":"/ʃɛl/","definition":"the hard outside cover of some animals","arabic":"صَدَفة / درع","example":"A turtle's shell is hard.","image_id":"IMG-RW-L03-U1-LS1-V13","audio_id":"AUD-RW-L03-U1-LS1-V13","tier":"core"},{"word":"survive","pos":"verb","ipa":"/sərˈvaɪv/","definition":"to stay alive, even in a hard place","arabic":"يبقى على قيد الحياة","example":"Camels can survive without water for many days.","image_id":"IMG-RW-L03-U1-LS1-V14","audio_id":"AUD-RW-L03-U1-LS1-V14","tier":"core"},{"word":"adapt","pos":"verb","ipa":"/əˈdæpt/","definition":"to change in ways that help you live in a place","arabic":"يتكيّف","example":"Desert animals adapt to the heat.","image_id":"IMG-RW-L03-U1-LS1-V15","audio_id":"AUD-RW-L03-U1-LS1-V15","tier":"tier2"},{"word":"explain","pos":"verb","ipa":"/ɪkˈspleɪn/","definition":"to make something clear by telling more about it","arabic":"يشرح","example":"Explain how fur helps the fox.","image_id":"IMG-RW-L03-U1-LS1-V16","audio_id":"AUD-RW-L03-U1-LS1-V16","tier":"tier2"},{"word":"support","pos":"verb","ipa":"/səˈpɔrt/","definition":"to give facts or reasons that show an idea is true","arabic":"يدعم","example":"Use details to support the main idea.","image_id":"IMG-RW-L03-U1-LS1-V17","audio_id":"AUD-RW-L03-U1-LS1-V17","tier":"tier2"}],"explanation":{"text":"Writers often **explain a new word in the same sentence**. This is a **definition clue**. When you see a new word, look **right next to it**.\n\nDefinition clues often follow these signals: **is / are**, **means**, **or**, **called**, a **comma** (,) or a **dash** (–). *A **burrow** is a hole in the ground where an animal lives.*\n\nSteps: (1) Find the new word. (2) Look for a signal word or punctuation. (3) Read the words after the signal – that is the meaning. (4) Put the meaning back into the sentence to check that it makes sense.","examples":["**is**: *A **habitat** is the natural home of an animal.* → habitat = natural home.","**means**: *To **survive** means to stay alive.* → survive = stay alive.","**or**: *The fox digs a **burrow**, or a tunnel under the sand.* → burrow = tunnel under the sand.","**called**: *Hard nails on a bird's feet are called **claws**.* → claws = hard nails on feet.","**comma**: *Owls **hunt**, chase and catch other animals, at night.* → hunt = chase and catch animals.","**dash**: *Turtles have a **shell** – a hard cover on their back.* → shell = hard cover.","**which is**: *Many birds build a **nest**, which is a home made of sticks and grass.*","Check it: *The camel can **stay alive** in the desert.* → it makes sense, so *survive* = stay alive.","No clue? Use the picture, read the next sentence or check the glossary."],"common_errors":["✗ Stopping at the new word and skipping the sentence. → ✓ Read the whole sentence; the meaning is often right after the word. (Look **right next to** the word.)","✗ Thinking *or* always means a choice. → ✓ *a burrow, or a tunnel* – here **or** gives another name (the meaning). (**or** after a comma can mean 'in other words'.)","✗ The fox have thick fur. → ✓ The fox has thick fur. (One fox → **has**.)","✗ Birds has feathers. → ✓ Birds have feathers. (Many birds → **have**.)","✗ The turtle protect itself with its shell. → ✓ The turtle protects itself with its shell. (One turtle → **protects**.)","✗ a desert animals → ✓ a desert animal / desert animals (**a** + one; no **a** with plurals.)","✗ The camels can survives. → ✓ Camels can survive. (After **can**, use the base verb.)"],"arabic":"كثيرًا ما يشرح الكاتب الكلمة الجديدة في الجملة نفسها، وهذا يسمى دليل التعريف.\n\nإشارات دليل التعريف: is/are، means، or، called، الفاصلة (,) أو الشَّرطة (–).\n\nالخطوات: جِد الكلمة الجديدة، ثم ابحث عن الإشارة، ثم اقرأ الكلمات بعدها فهي المعنى، ثم ضع المعنى مكان الكلمة لتتأكد أنه مناسب.\n\nانتبه: كلمة or بعد فاصلة قد تعني «أي» أو «بعبارة أخرى» وليس الاختيار."},"video":{"script":[{"time":"00:00–00:20","narration":"Adam the Researcher is visiting animal homes around the world!","on_screen":"Amazing Animals","visual":"Adam's wheelchair rolls onto a big world map; pins pop up in a desert, an ocean and a forest."},{"time":"00:20–01:00","narration":"Every animal has a habitat: the desert, the ocean, the forest. Some live in a nest or a burrow.","on_screen":"habitat · desert · ocean · forest · nest · burrow","visual":"The camera zooms into each habitat and home."},{"time":"01:00–01:35","narration":"Claws, feathers, fur and a shell help animals hunt, hide, protect themselves and survive.","on_screen":"claws · feathers · fur · shell · hunt · hide · protect · survive","visual":"A falcon's claws, an owl's feathers, a fox's fur and a turtle's shell are shown up close."},{"time":"01:35–02:25","narration":"New word? Look right next to it! A burrow IS a hole in the ground. To survive MEANS to stay alive. A burrow, OR a tunnel…","on_screen":"Signals: is · means · or · called · , · –","visual":"Signal words light up like arrows pointing to the meaning."},{"time":"02:25–02:45","narration":"Put the meaning back in the sentence. Does it make sense? Yes!","on_screen":"Check it ✔","visual":"The definition slides into the sentence in place of the word."},{"time":"02:45–03:00","narration":"Animals adapt to their homes. Can you explain how?","on_screen":"adapt · explain · support","visual":"Saqr fluffs his feathers and winks."}],"captions_ar":["آدم الباحث يزور بيوت الحيوانات حول العالم!","لكل حيوان موطن: الصحراء والمحيط والغابة، وبعضها يعيش في عش أو جحر.","المخالب والريش والفرو والصدفة تساعد الحيوانات على الصيد والاختباء وحماية نفسها والبقاء.","كلمة جديدة؟ انظر بجانبها! الجحر هو حفرة في الأرض، وsurvive تعني يبقى حيًا.","ضع المعنى مكان الكلمة: هل الجملة مفهومة؟ نعم!","الحيوانات تتكيّف مع بيئاتها. هل تستطيع أن تشرح كيف؟"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Adam (the Researcher): curious, clear boy voice."},"texts":[],"activities":[{"id":"RW-L03-U1-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the correct word.","instructions_ar":"اختر الكلمة الصحيحة.","items":[{"q":"A very dry place with little rain and lots of sand is a ___.","answer":"desert","explanation":"Dry and sandy = desert.","explanation_ar":"صحراء.","options":["desert","forest","ocean","nest"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Whales and sharks live in the salty ___.","answer":"ocean","explanation":"Big salt water = ocean.","explanation_ar":"المحيط.","options":["burrow","desert","forest","ocean"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A bird builds a ___ from sticks and grass.","answer":"nest","explanation":"Bird home = nest.","explanation_ar":"عُش.","options":["shell","nest","burrow","habitat"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"The fennec fox sleeps in a ___ under the sand.","answer":"burrow","explanation":"A hole in the ground = burrow.","explanation_ar":"جُحر.","options":["nest","shell","forest","burrow"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"The falcon catches a mouse with its sharp ___.","answer":"claws","explanation":"Sharp nails = claws.","explanation_ar":"مخالب.","options":["claws","feathers","fur","shell"],"dok":1,"skill":"body parts","stage":"controlled"},{"q":"A turtle's hard ___ keeps it safe.","answer":"shell","explanation":"Hard cover = shell.","explanation_ar":"صدفة.","options":["fur","nest","shell","feathers"],"dok":1,"skill":"body parts","stage":"controlled"}]},{"id":"RW-L03-U1-LS1-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Find the definition clue. Choose the meaning.","instructions_ar":"جِد دليل التعريف واختر المعنى.","items":[{"q":"*A **habitat** is the natural home of an animal.* What does *habitat* mean?","answer":"the natural home of an animal","explanation":"Signal: is.","explanation_ar":"الموطن الطبيعي.","options":["a kind of food","the natural home of an animal","a sharp claw","a big ocean wave"],"dok":1,"skill":"definition clues","stage":"guided"},{"q":"*Owls **hunt**, or chase and catch other animals, at night.* Which signal word helps you?","answer":"or","explanation":"*or* introduces the meaning.","explanation_ar":"or.","options":["or","Owls","at","night"],"dok":2,"skill":"signal words","stage":"guided"},{"q":"*To **survive** means to stay alive.* What does *survive* mean?","answer":"to stay alive","explanation":"Signal: means.","explanation_ar":"يبقى حيًا.","options":["to sleep all day","to build a nest","to stay alive","to swim fast"],"dok":1,"skill":"definition clues","stage":"guided"},{"q":"*Some animals **camouflage** – they hide by looking like the things around them.* What does *camouflage* mean?","answer":"hide by looking like the things around them","explanation":"Signal: dash.","explanation_ar":"التمويه.","options":["run very fast","eat plants","hide by looking like the things around them","make loud sounds"],"dok":2,"skill":"definition clues","stage":"guided"},{"q":"*Animals that hunt other animals are called **predators**.* What is a predator?","answer":"an animal that hunts other animals","explanation":"Signal: called.","explanation_ar":"المفترس.","options":["a baby animal","an animal that hunts other animals","a kind of nest","an animal that eats only plants"],"dok":2,"skill":"definition clues","stage":"guided"},{"q":"*Many birds **migrate**, which means they fly to warmer places in winter.* What does *migrate* mean?","answer":"fly to warmer places in winter","explanation":"Signal: which means.","explanation_ar":"يهاجر.","options":["build a new nest","lose their feathers","hunt in the ocean","fly to warmer places in winter"],"dok":2,"skill":"definition clues","stage":"guided"}]},{"id":"RW-L03-U1-LS1-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"Desert animals ________ to the heat. For example, the fox has big ears to stay cool.","answer":"adapt","explanation":"Change in ways that help them live.","explanation_ar":"تتكيّف.","stage":"freer"},{"q":"Can you ________ how feathers help birds fly?","answer":"explain","explanation":"Make it clear.","explanation_ar":"تشرح.","stage":"freer"},{"q":"Use facts from the text to ________ your answer.","answer":"support","explanation":"Show it is true.","explanation_ar":"تدعم.","stage":"freer"},{"q":"Mother birds ________ their eggs from snakes.","answer":"protect","explanation":"Keep safe.","explanation_ar":"تحمي.","stage":"freer"},{"q":"The mouse runs to ________ under a bush.","answer":"hide","explanation":"Go where others cannot see.","explanation_ar":"يختبئ.","stage":"freer"},{"q":"Thick ________ keeps the fox warm on cold desert nights.","answer":"fur","explanation":"Soft hair.","explanation_ar":"الفرو.","stage":"freer"}]},{"id":"RW-L03-U1-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write with the new words.","instructions_ar":"اكتب باستخدام الكلمات الجديدة.","items":[{"q":"Write a sentence with a definition clue for *nest*. Use *is* or *which is*.","answer":"A nest is a home that birds build from sticks and grass.","explanation":"Word + is + meaning.","explanation_ar":"الكلمة + is + المعنى.","dok":2,"skill":"definition clues","stage":"production"},{"q":"Write a sentence with a definition clue for *forest*. Use *or*.","answer":"Owls live in the forest, or a place with many tall trees.","explanation":"Word + , or + meaning.","explanation_ar":"الكلمة + , or + المعنى.","dok":2,"skill":"definition clues","stage":"production"},{"q":"Explain how ONE body part helps an animal survive.","answer":"A turtle's shell protects it from other animals, so it can survive.","explanation":"Body part + how it helps.","explanation_ar":"جزء من الجسم + كيف يساعد.","dok":3,"skill":"explain","stage":"production"},{"q":"Which habitat would you like to visit? Why?","answer":"I would like to visit the ocean because I want to see sea turtles.","explanation":"Habitat + because.","explanation_ar":"بيئة + because.","dok":2,"skill":"opinion","stage":"production"}]}],"game":{"name":"Habitat Hop","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Habitat match: an animal card floats down; the child drags it to the desert, ocean or forest. Every third card shows a sentence with a definition clue; the child taps the signal word and then the meaning.","The teacher shows an animal card (camel, sea turtle, owl, fennec fox, whale, woodpecker).","Students hop to the right habitat area.","The teacher reads a clue sentence about the animal.","Students in the right area say the meaning of the bold word and the signal word.","Right habitat + right meaning = 2 points for the team."],"data":[]},"exit_quiz":[{"q":"Which word means *the natural home of an animal*?","answer":"habitat","explanation":"Habitat = natural home.","explanation_ar":"الموطن.","options":["survive","claws","hunt","habitat"],"dok":1,"skill":"vocabulary"},{"q":"Which signal word often comes right before a definition?","answer":"means","explanation":"*means* introduces a meaning.","explanation_ar":"means.","options":["but","then","because","means"],"dok":1,"skill":"signal words"},{"q":"Which animal lives in a burrow?","answer":"a fennec fox","explanation":"Foxes dig burrows.","explanation_ar":"الثعلب.","options":["an eagle","a whale","a fennec fox","a parrot"],"dok":1,"skill":"vocabulary"},{"q":"Which body part helps a bird fly?","answer":"feathers","explanation":"Feathers help birds fly.","explanation_ar":"الريش.","options":["feathers","fur","a shell","claws"],"dok":1,"skill":"body parts"},{"q":"*The hedgehog has **spines**, or sharp hairs on its back.* What are spines?","answer":"sharp hairs on its back","explanation":"Signal: or.","explanation_ar":"شعيرات حادة.","options":["sharp hairs on its back","soft feet","long ears","big eyes"],"dok":2,"skill":"definition clues"},{"q":"Which sentence about a camel is correct?","answer":"Camels can survive in the hot desert.","explanation":"can + base verb.","explanation_ar":"can + فعل مجرد.","options":["Camels can survives in the hot desert.","Camels survives in the hot desert.","Camels can survive in the hot desert.","A camels can survive in the desert."],"dok":2,"skill":"grammar"},{"q":"*Animals adapt to their habitats.* *Adapt* means ___.","answer":"change in ways that help them live there","explanation":"Adapt = change to fit.","explanation_ar":"تتكيّف.","options":["run away","change in ways that help them live there","sleep all winter","lose their homes"],"dok":2,"skill":"vocabulary"},{"q":"After you find a meaning, how can you check it?","answer":"Put the meaning in place of the word and see if the sentence makes sense.","explanation":"Check by replacing.","explanation_ar":"ضع المعنى مكان الكلمة.","options":["Skip the sentence.","Put the meaning in place of the word and see if the sentence makes sense.","Read only the title.","Ask your friend to read it."],"dok":2,"skill":"strategy"},{"q":"*A sea turtle's shell protects it.* How does the shell help the turtle survive?","answer":"It keeps the turtle safe from danger.","explanation":"Protect = keep safe.","explanation_ar":"يحميها من الخطر.","options":["It helps the turtle fly.","It keeps the turtle cold.","It keeps the turtle safe from danger.","It helps the turtle hunt in trees."],"dok":3,"skill":"explain"},{"q":"Why do writers put definition clues in a text?","answer":"to help readers understand new words without stopping","explanation":"Clues help readers.","explanation_ar":"لمساعدة القارئ على الفهم.","options":["to make the text longer","to hide the main idea","to make it a poem","to help readers understand new words without stopping"],"dok":3,"skill":"author's purpose"}],"images":[{"id":"IMG-RW-L03-U1-LS1-V01","prompt":"Picture for the word 'habitat': a desert scene with a camel and a lizard"},{"id":"IMG-RW-L03-U1-LS1-V02","prompt":"Picture for the word 'desert': sand dunes under a bright sun"},{"id":"IMG-RW-L03-U1-LS1-V03","prompt":"Picture for the word 'ocean': blue ocean waves with a whale tail"},{"id":"IMG-RW-L03-U1-LS1-V04","prompt":"Picture for the word 'forest': a green forest with tall trees"},{"id":"IMG-RW-L03-U1-LS1-V05","prompt":"Picture for the word 'nest': a bird's nest with three eggs"},{"id":"IMG-RW-L03-U1-LS1-V06","prompt":"Picture for the word 'burrow': a cutaway of a burrow under the sand"},{"id":"IMG-RW-L03-U1-LS1-V07","prompt":"Picture for the word 'hunt': an owl swooping toward a mouse"},{"id":"IMG-RW-L03-U1-LS1-V08","prompt":"Picture for the word 'hide': a lizard half under a rock"},{"id":"IMG-RW-L03-U1-LS1-V09","prompt":"Picture for the word 'protect': a turtle pulling into its shell"},{"id":"IMG-RW-L03-U1-LS1-V10","prompt":"Picture for the word 'claws': a falcon's feet with sharp claws"},{"id":"IMG-RW-L03-U1-LS1-V11","prompt":"Picture for the word 'feathers': colorful feathers"},{"id":"IMG-RW-L03-U1-LS1-V12","prompt":"Picture for the word 'fur': a close-up of soft orange fur"},{"id":"IMG-RW-L03-U1-LS1-V13","prompt":"Picture for the word 'shell': a turtle shell with patterns"},{"id":"IMG-RW-L03-U1-LS1-V14","prompt":"Picture for the word 'survive': a camel walking across hot dunes"},{"id":"IMG-RW-L03-U1-LS1-V15","prompt":"Picture for the word 'adapt': a fennec fox with big ears in the sand"},{"id":"IMG-RW-L03-U1-LS1-V16","prompt":"Picture for the word 'explain': a teacher pointing at a diagram"},{"id":"IMG-RW-L03-U1-LS1-V17","prompt":"Picture for the word 'support': pillars holding up a roof labelled 'main idea'"},{"id":"IMG-RW-L03-U1-LS1-01","prompt":"Animals in a desert, an ocean and a forest, with Adam holding binoculars."},{"id":"IMG-RW-L03-U1-LS1-02","prompt":"Close-ups of claws, feathers, fur and a shell."},{"id":"IMG-RW-L03-U1-LS1-03","prompt":"A sentence with an arrow from the signal word to the meaning."}],"audio":[{"id":"AUD-RW-L03-U1-LS1-V01","script":"habitat. The desert is the camel's habitat."},{"id":"AUD-RW-L03-U1-LS1-V02","script":"desert. Few plants grow in the desert."},{"id":"AUD-RW-L03-U1-LS1-V03","script":"ocean. Whales live in the ocean."},{"id":"AUD-RW-L03-U1-LS1-V04","script":"forest. Owls live in the forest."},{"id":"AUD-RW-L03-U1-LS1-V05","script":"nest. The bird lays eggs in its nest."},{"id":"AUD-RW-L03-U1-LS1-V06","script":"burrow. The fox sleeps in a burrow."},{"id":"AUD-RW-L03-U1-LS1-V07","script":"hunt. Owls hunt at night."},{"id":"AUD-RW-L03-U1-LS1-V08","script":"hide. The lizard hides under a rock."},{"id":"AUD-RW-L03-U1-LS1-V09","script":"protect. A shell protects the turtle."},{"id":"AUD-RW-L03-U1-LS1-V10","script":"claws. The falcon catches food with its claws."},{"id":"AUD-RW-L03-U1-LS1-V11","script":"feathers. Feathers keep birds warm and help them fly."},{"id":"AUD-RW-L03-U1-LS1-V12","script":"fur. The fox has thick fur."},{"id":"AUD-RW-L03-U1-LS1-V13","script":"shell. A turtle's shell is hard."},{"id":"AUD-RW-L03-U1-LS1-V14","script":"survive. Camels can survive without water for many days."},{"id":"AUD-RW-L03-U1-LS1-V15","script":"adapt. Desert animals adapt to the heat."},{"id":"AUD-RW-L03-U1-LS1-V16","script":"explain. Explain how fur helps the fox."},{"id":"AUD-RW-L03-U1-LS1-V17","script":"support. Use details to support the main idea."},{"id":"AUD-RW-L03-U1-LS1-VID","script":"Adam the Researcher is visiting animal homes around the world! Every animal has a habitat: the desert, the ocean, the forest. Some live in a nest or a burrow. Claws, feathers, fur and a shell help animals hunt, hide, protect themselves and survive. New word? Look right next to it! A burrow IS a hole in the ground. To survive MEANS to stay alive. A burrow, OR a tunnel… Put the meaning back in the sentence. Does it make sense? Yes! Animals adapt to their homes. Can you explain how?"}]},{"id":"RW-L03-U1-LS2","title":"Homes in the Wild","lesson_type":"close_reading","objectives":["read an informational article of about 190 words with headings and find key facts","answer 'Right There' and 'Think and Search' questions using evidence from the text","explain how an animal's body helps it survive in its habitat (cause and effect)"],"objectives_ar":["قراءة مقال معلوماتي من نحو 190 كلمة فيه عناوين فرعية وإيجاد الحقائق الرئيسية.","الإجابة عن أسئلة «موجودة هنا» و«فكّر وابحث» باستخدام الدليل من النص.","شرح كيف يساعد جسم الحيوان على البقاء في بيئته (سبب ونتيجة)."],"success_criteria":["I can find a 'Right There' answer in one sentence.","I can put facts from two places together for a 'Think and Search' answer.","I can quote evidence to support my answer."],"success_criteria_ar":["أستطيع إيجاد إجابة «موجودة هنا» في جملة واحدة.","أستطيع جمع حقائق من مكانين لإجابة «فكّر وابحث».","أستطيع الاستشهاد بالدليل لدعم إجابتي."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"natural","pos":"adjective","ipa":"/ˈnætʃərəl/","definition":"made by nature, not by people","arabic":"طبيعي","example":"A burrow is a natural home.","image_id":"IMG-RW-L03-U1-LS2-V01","audio_id":"AUD-RW-L03-U1-LS2-V01","tier":"core"},{"word":"rest","pos":"verb","ipa":"/rɛst/","definition":"to stop and relax or sleep","arabic":"يستريح","example":"Animals need a safe place to rest.","image_id":"IMG-RW-L03-U1-LS2-V02","audio_id":"AUD-RW-L03-U1-LS2-V02","tier":"core"},{"word":"wide","pos":"adjective","ipa":"/waɪd/","definition":"big from one side to the other","arabic":"عريض","example":"Camels have wide feet.","image_id":"IMG-RW-L03-U1-LS2-V03","audio_id":"AUD-RW-L03-U1-LS2-V03","tier":"core"},{"word":"sink","pos":"verb","ipa":"/sɪŋk/","definition":"to go down into something soft or into water","arabic":"يغوص","example":"Wide feet do not sink in the sand.","image_id":"IMG-RW-L03-U1-LS2-V04","audio_id":"AUD-RW-L03-U1-LS2-V04","tier":"core"},{"word":"salty","pos":"adjective","ipa":"/ˈsɔlti/","definition":"with salt in it","arabic":"مالح","example":"Ocean water is salty.","image_id":"IMG-RW-L03-U1-LS2-V05","audio_id":"AUD-RW-L03-U1-LS2-V05","tier":"core"},{"word":"flippers","pos":"noun","ipa":"/ˈflɪpərz/","definition":"flat arms or legs that help sea animals swim","arabic":"زعانف","example":"Sea turtles use their flippers to swim.","image_id":"IMG-RW-L03-U1-LS2-V06","audio_id":"AUD-RW-L03-U1-LS2-V06","tier":"core"},{"word":"evidence","pos":"noun","ipa":"/ˈɛvɪdəns/","definition":"words or facts from the text that show your answer is right","arabic":"دليل","example":"Give evidence from the text.","image_id":"IMG-RW-L03-U1-LS2-V07","audio_id":"AUD-RW-L03-U1-LS2-V07","tier":"core"}],"explanation":{"text":"Questions about a text are not all the same. Knowing the **type** of question helps you find the answer.\n\n**Right There** questions: the answer is in **one sentence**. The question words often match the text words. *What do camels' wide feet do? → Their wide feet do not sink in the sand.*\n\n**Think and Search** questions: the answer is in **two or more places**. You must **find and put together** facts. Always give **evidence** – the words from the text that support your answer.","examples":["Right There: *What is an animal's natural home called?* → **its habitat** (paragraph 1).","Right There: *What do owls hunt at night?* → **mice** (Life in the Forest).","Right There: *What protects sea turtles from sharks?* → **their hard shells**.","Think and Search: *How does the fennec fox stay comfortable in the desert?* → **It digs a burrow to stay cool, AND its thick fur keeps it warm at night.** (two facts)","Think and Search: *What three things does a habitat give an animal?* → **food, water and a safe place to rest**.","Think and Search: *Name two body parts that help owls.* → **sharp claws (to hunt) and soft feathers (to fly quietly)**.","Evidence frame: **The text says, \"…\"** or **In the section *Life in the Ocean*, it says…**","Cause → effect: *Camels have wide feet,* **so** *they do not sink in the sand.*","Use the **headings** to jump to the right section quickly."],"common_errors":["✗ Answering from memory: 'Camels drink a lot of water.' → ✓ The text says camels can walk for days without drinking water. (Answer from the **text**, not from guesses.)","✗ Giving one fact for a Think and Search question. → ✓ Give **all** the facts: burrow (cool) and fur (warm). (Search **more than one** place.)","✗ The fox dig a burrow. → ✓ The fox digs a burrow. (One fox → **digs**.)","✗ Owls hunts mice. → ✓ Owls hunt mice. (Many owls → **hunt**.)","✗ Evidence: 'I think so.' → ✓ Evidence: The text says, \"Their hard shells protect them from sharks.\" (Evidence = words **from the text**.)","✗ Sea turtles swims for many kilometer. → ✓ Sea turtles swim for many kilometers. (Many turtles → **swim**; many → **kilometers**.)"],"arabic":"ليست كل الأسئلة متشابهة؛ معرفة نوع السؤال تساعدك على إيجاد الإجابة.\n\nأسئلة «موجودة هنا» (Right There): الإجابة في جملة واحدة، وغالبًا تتشابه كلمات السؤال مع كلمات النص.\n\nأسئلة «فكّر وابحث» (Think and Search): الإجابة في مكانين أو أكثر، فعليك أن تجد الحقائق وتجمعها.\n\nقدّم دائمًا الدليل (evidence): الكلمات من النص التي تدعم إجابتك، مثل: The text says, \"…\"."},"video":{"script":[{"time":"00:00–00:20","narration":"Adam has two kinds of questions in his research notebook!","on_screen":"Right There 👉 · Think and Search 🔍","visual":"Adam's notebook opens with two colored tabs."},{"time":"00:20–01:35","narration":"Homes in the Wild. Every animal needs a home…","on_screen":"(article, section by section)","visual":"Live-action style animation: desert (camel, fennec fox at burrow), ocean (sea turtle and flippers), forest (owl in a tree hole hunting silently)."},{"time":"01:35–02:05","narration":"Right There: What protects sea turtles from sharks? Look – it's right there in one sentence: their hard shells!","on_screen":"Right There = one sentence","visual":"A finger points to one highlighted sentence."},{"time":"02:05–02:40","narration":"Think and Search: How does the fennec fox stay comfortable? Search: burrow – stay cool… AND fur – keeps warm!","on_screen":"Think and Search = 2+ places","visual":"Two sentences light up in different places; a line joins them."},{"time":"02:40–03:00","narration":"Always show your evidence: The text says…!","on_screen":"The text says, \"…\"","visual":"Saqr holds up a magnifying glass and a quote bubble."}],"captions_ar":["عند آدم نوعان من الأسئلة في دفتر بحثه!","بيوت في البرية: كل حيوان يحتاج إلى بيت…","«موجودة هنا»: ما الذي يحمي السلاحف البحرية من أسماك القرش؟ الإجابة في جملة واحدة: صدفتها الصلبة!","«فكّر وابحث»: كيف يبقى ثعلب الفنك مرتاحًا؟ الجحر يبقيه باردًا، والفرو يدفئه ليلًا!","اعرض دليلك دائمًا: The text says…"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Adam: curious researcher voice."},"texts":[{"type":"reading","title":"Homes in the Wild","body":"Every animal needs a home. An animal's natural home is called its habitat. A habitat gives an animal food, water and a safe place to rest. Animals have special body parts that help them survive in their habitats.\n\n**Life in the Desert**\n\nThe desert is very hot in the day and cold at night. Camels can walk for days without drinking water. Their wide feet do not sink in the sand. The fennec fox digs a burrow under the sand to stay cool, and its thick fur keeps it warm at night.\n\n**Life in the Ocean**\n\nThe ocean is full of salty water. Sea turtles swim for many kilometers. Their hard shells protect them from sharks, and their flippers, or flat arms, help them swim.\n\n**Life in the Forest**\n\nA forest has many trees. Owls build nests in tree holes. They hunt mice at night with their sharp claws. Their soft feathers help them fly without a sound.\n\nEvery habitat is different, but each animal has what it needs to survive there.","word_count":172,"audio_id":"AUD-RW-L03-U1-LS2-T1","id":"TXT-RW-L03-U1-LS2-1","genre":"informational","role":"main","difficulty":"350L–500L","glossary":[{"word":"sink","definition":"go down into something soft or into water","arabic":"يغوص / يغرق"},{"word":"flippers","definition":"flat arms that help sea animals swim","arabic":"زعانف"},{"word":"without a sound","definition":"very quietly","arabic":"دون صوت"}]}],"activities":[{"id":"RW-L03-U1-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Right There questions. Choose the answer.","instructions_ar":"أسئلة «موجودة هنا»: اختر الإجابة.","items":[{"q":"What is an animal's natural home called?","answer":"its habitat","explanation":"Paragraph 1: called its habitat.","explanation_ar":"موطنه.","options":["its habitat","its burrow only","its ocean","its shell"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How long can camels walk without drinking water?","answer":"for days","explanation":"Text: for days.","explanation_ar":"لأيام.","options":["for one hour","for a year","for days","for ten minutes"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What does the fennec fox dig?","answer":"a burrow under the sand","explanation":"Life in the Desert.","explanation_ar":"جحرًا تحت الرمل.","options":["a nest in a tree","a burrow under the sand","a hole in the ocean","a road"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What do sea turtles use to swim?","answer":"their flippers","explanation":"Text: flippers… help them swim.","explanation_ar":"زعانفها.","options":["their flippers","their claws","their shells","their feathers"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Where do owls build their nests?","answer":"in tree holes","explanation":"Life in the Forest.","explanation_ar":"في ثقوب الأشجار.","options":["under the sand","in the ocean","on camels","in tree holes"],"dok":1,"skill":"key details: where","stage":"controlled"},{"q":"What do owls hunt at night?","answer":"mice","explanation":"Text: They hunt mice.","explanation_ar":"الفئران.","options":["fish","mice","camels","turtles"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L03-U1-LS2-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Think and Search questions. Choose the answer.","instructions_ar":"أسئلة «فكّر وابحث»: اختر الإجابة.","items":[{"q":"What three things does a habitat give an animal?","answer":"food, water and a safe place to rest","explanation":"All in paragraph 1.","explanation_ar":"طعام وماء ومكان آمن.","options":["sand, trees and water","fur, claws and feathers","sharks, mice and camels","food, water and a safe place to rest"],"dok":2,"skill":"key details","stage":"guided"},{"q":"How does the fennec fox stay comfortable day AND night?","answer":"Its burrow keeps it cool, and its fur keeps it warm.","explanation":"Two facts from the desert section.","explanation_ar":"الجحر يبرّده والفرو يدفئه.","options":["It drinks water all day.","Its burrow keeps it cool, and its fur keeps it warm.","It swims in the ocean.","It sleeps in a tree hole."],"dok":2,"skill":"synthesize","stage":"guided"},{"q":"Which two body parts help owls?","answer":"sharp claws and soft feathers","explanation":"Forest section.","explanation_ar":"مخالب حادة وريش ناعم.","options":["sharp claws and soft feathers","a hard shell and flippers","wide feet and thick fur","big ears and a burrow"],"dok":2,"skill":"synthesize","stage":"guided"},{"q":"Which animal in the article lives in salty water?","answer":"the sea turtle","explanation":"The ocean is salty; sea turtles live there.","explanation_ar":"السلحفاة البحرية.","options":["the camel","the owl","the fennec fox","the sea turtle"],"dok":2,"skill":"connect details","stage":"guided"},{"q":"Why don't camels sink in the sand?","answer":"They have wide feet.","explanation":"Cause: wide feet → effect: do not sink.","explanation_ar":"أقدامها عريضة.","options":["They have hard shells.","They have feathers.","They have wide feet.","They walk at night."],"dok":2,"skill":"cause and effect","stage":"guided"},{"q":"Why can owls catch mice easily at night?","answer":"They fly without a sound and have sharp claws.","explanation":"Put two forest facts together.","explanation_ar":"يطير بصمت ومخالبه حادة.","options":["They fly without a sound and have sharp claws.","They are very big and loud.","They swim fast.","They dig burrows."],"dok":3,"skill":"inference","stage":"guided"}]},{"id":"RW-L03-U1-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Find the evidence.","instructions_ar":"ابحث عن الدليل.","items":[{"q":"Underline the sentence that tells what protects sea turtles from sharks.","answer":"Their hard shells protect them from sharks, and their flippers, or flat arms, help them swim.","explanation":"Right There sentence.","explanation_ar":"جملة الدليل.","evidence":"Their hard shells protect them from sharks, and their flippers, or flat arms, help them swim.","text_id":"TXT-RW-L03-U1-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["Every animal needs a home.","An animal's natural home is called its habitat.","A habitat gives an animal food, water and a safe place to rest.","Animals have special body parts that help them survive in their habitats.","**Life in the Desert**","The desert is very hot in the day and cold at night.","Camels can walk for days without drinking water.","Their wide feet do not sink in the sand.","The fennec fox digs a burrow under the sand to stay cool, and its thick fur keeps it warm at night.","**Life in the Ocean**","The ocean is full of salty water.","Sea turtles swim for many kilometers.","Their hard shells protect them from sharks, and their flippers, or flat arms, help them swim.","**Life in the Forest**","A forest has many trees.","Owls build nests in tree holes.","They hunt mice at night with their sharp claws.","Their soft feathers help them fly without a sound.","Every habitat is different, but each animal has what it needs to survive there."]},{"q":"Underline the sentence that tells how the desert changes from day to night.","answer":"The desert is very hot in the day and cold at night.","explanation":"Day vs. night.","explanation_ar":"النهار مقابل الليل.","evidence":"The desert is very hot in the day and cold at night.","text_id":"TXT-RW-L03-U1-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["Every animal needs a home.","An animal's natural home is called its habitat.","A habitat gives an animal food, water and a safe place to rest.","Animals have special body parts that help them survive in their habitats.","**Life in the Desert**","The desert is very hot in the day and cold at night.","Camels can walk for days without drinking water.","Their wide feet do not sink in the sand.","The fennec fox digs a burrow under the sand to stay cool, and its thick fur keeps it warm at night.","**Life in the Ocean**","The ocean is full of salty water.","Sea turtles swim for many kilometers.","Their hard shells protect them from sharks, and their flippers, or flat arms, help them swim.","**Life in the Forest**","A forest has many trees.","Owls build nests in tree holes.","They hunt mice at night with their sharp claws.","Their soft feathers help them fly without a sound.","Every habitat is different, but each animal has what it needs to survive there."]},{"q":"Which sentence gives the MAIN IDEA of the whole article?","answer":"Animals have special body parts that help them survive in their habitats.","explanation":"It covers all three sections.","explanation_ar":"الفكرة الرئيسية.","options":["Owls build nests in tree holes.","The ocean is full of salty water.","Animals have special body parts that help them survive in their habitats.","Camels can walk for days."],"dok":3,"skill":"main idea","stage":"freer"},{"q":"The writer uses *flippers, or flat arms*. Why?","answer":"to explain a new word with a definition clue","explanation":"Definition clue with *or*.","explanation_ar":"لشرح كلمة جديدة.","options":["to tell a story","to explain a new word with a definition clue","to give a heading","to ask a question"],"dok":2,"skill":"author's craft","stage":"freer"}]},{"id":"RW-L03-U1-LS2-A4","type":"open","stage":"production","instructions":"Writing: Answer with evidence.","instructions_ar":"أجب مع الدليل.","items":[{"q":"Why do camels need wide feet? Give evidence.","answer":"Camels need wide feet so they do not sink. The text says, \"Their wide feet do not sink in the sand.\"","explanation":"Answer + The text says.","explanation_ar":"إجابة + الدليل.","dok":2,"skill":"evidence","stage":"production"},{"q":"How is the desert different at night? What helps the fox at night?","answer":"The desert is cold at night. The fox's thick fur keeps it warm.","explanation":"Two facts.","explanation_ar":"حقيقتان.","dok":2,"skill":"synthesize","stage":"production"},{"q":"Which animal in the article is the best at surviving? Explain with one fact.","answer":"The camel, because it can walk for days without drinking water.","explanation":"Opinion + fact.","explanation_ar":"رأي + حقيقة.","dok":3,"skill":"evaluate","stage":"production"},{"q":"Write your own Think and Search question about the article and answer it.","answer":"Q: Which animals in the article have special homes? A: The fox has a burrow, and the owl has a nest in a tree hole.","explanation":"Question + answer from 2 places.","explanation_ar":"سؤال + إجابة من مكانين.","dok":3,"skill":"questioning","stage":"production"}]},{"id":"RW-L03-U1-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Homes in the Wild\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Homes in the Wild”.","answer":"172 words","title":"Homes in the Wild","body":"Every animal needs a home. An animal's natural home is called its habitat. A habitat gives an animal food, water and a safe place to rest. Animals have special body parts that help them survive in their habitats.\n\n**Life in the Desert**\n\nThe desert is very hot in the day and cold at night. Camels can walk for days without drinking water. Their wide feet do not sink in the sand. The fennec fox digs a burrow under the sand to stay cool, and its thick fur keeps it warm at night.\n\n**Life in the Ocean**\n\nThe ocean is full of salty water. Sea turtles swim for many kilometers. Their hard shells protect them from sharks, and their flippers, or flat arms, help them swim.\n\n**Life in the Forest**\n\nA forest has many trees. Owls build nests in tree holes. They hunt mice at night with their sharp claws. Their soft feathers help them fly without a sound.\n\nEvery habitat is different, but each animal has what it needs to survive there.","words":172,"limit":162}],"time_limit_sec":162}],"game":{"name":"Question Detectives","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Evidence hunt: a question appears; the child picks 'Right There' or 'Think and Search', then taps the sentence(s) in the article that hold the answer. Correct evidence turns into a paw print trail.","Teams take turns drawing a question card (the color is hidden).","The team says the type, then finds and reads the evidence.","Turn the card over to check the color/type.","Correct type = 1 point; correct answer with evidence = 2 points.","The team with the most paw prints wins."],"data":[]},"exit_quiz":[{"q":"A *Right There* answer is found ___.","answer":"in one sentence","explanation":"Right There = one sentence.","explanation_ar":"في جملة واحدة.","options":["in the title only","in one sentence","in your head only","in another book"],"dok":1,"skill":"question types"},{"q":"A *Think and Search* answer is found ___.","answer":"in two or more places","explanation":"Think and Search = 2+ places.","explanation_ar":"في مكانين أو أكثر.","options":["in one word","in the glossary only","nowhere","in two or more places"],"dok":1,"skill":"question types"},{"q":"Which heading tells you about sea turtles?","answer":"Life in the Ocean","explanation":"Sea turtles live in the ocean.","explanation_ar":"Life in the Ocean.","options":["Life in the Desert","Life in the Forest","Life in the Ocean","Homes in the Wild"],"dok":1,"skill":"text features"},{"q":"*Their wide feet do not sink in the sand.* *Sink* means ___.","answer":"go down into something soft","explanation":"Sink = go down.","explanation_ar":"يغوص.","options":["jump very high","run fast","go down into something soft","dig a hole"],"dok":1,"skill":"vocabulary in context"},{"q":"Which is evidence for *Sea turtles can swim far*?","answer":"\"Sea turtles swim for many kilometers.\"","explanation":"It is about turtles swimming.","explanation_ar":"الدليل الصحيح.","options":["\"Sea turtles swim for many kilometers.\"","\"A forest has many trees.\"","\"Owls build nests in tree holes.\"","\"Camels can walk for days.\""],"dok":2,"skill":"evidence"},{"q":"Which question is Think and Search?","answer":"How do body parts help animals in all three habitats?","explanation":"Needs facts from all sections.","explanation_ar":"يحتاج إلى عدة أماكن.","options":["How do body parts help animals in all three habitats?","What do owls hunt?","What is the ocean full of?","Where do owls build nests?"],"dok":2,"skill":"question types"},{"q":"Why does the fennec fox need thick fur in the hot desert?","answer":"The desert is cold at night.","explanation":"Desert nights are cold.","explanation_ar":"لأن الصحراء باردة ليلًا.","options":["It swims in cold water.","It lives in the forest.","The desert is cold at night.","It has no burrow."],"dok":2,"skill":"inference"},{"q":"What does the last sentence of the article do?","answer":"It sums up the main idea: each animal has what it needs to survive.","explanation":"A closing sentence.","explanation_ar":"يلخص الفكرة الرئيسية.","options":["It tells a new story.","It asks a question.","It names a new habitat.","It sums up the main idea: each animal has what it needs to survive."],"dok":3,"skill":"text structure"},{"q":"Which detail would fit in a new section called *Life in the Mountains*?","answer":"Mountain goats have strong legs for climbing rocks.","explanation":"It matches a mountain habitat.","explanation_ar":"التفصيل المناسب.","options":["Sea turtles have flippers.","Mountain goats have strong legs for climbing rocks.","Owls hunt mice.","The desert is hot."],"dok":3,"skill":"apply"},{"q":"Why is it important to give evidence?","answer":"It shows your answer comes from the text.","explanation":"Evidence supports answers.","explanation_ar":"يُثبت أن إجابتك من النص.","options":["It shows your answer comes from the text.","It makes your answer shorter.","It replaces the question.","It is only for tests."],"dok":2,"skill":"strategy"}],"images":[{"id":"IMG-RW-L03-U1-LS2-V01","prompt":"Picture for the word 'natural': a forest stream with no buildings"},{"id":"IMG-RW-L03-U1-LS2-V02","prompt":"Picture for the word 'rest': a fox curled up resting"},{"id":"IMG-RW-L03-U1-LS2-V03","prompt":"Picture for the word 'wide': a camel's wide padded foot on sand"},{"id":"IMG-RW-L03-U1-LS2-V04","prompt":"Picture for the word 'sink': a boot sinking in sand next to a camel foot on top"},{"id":"IMG-RW-L03-U1-LS2-V05","prompt":"Picture for the word 'salty': a glass of sea water and a salt shaker"},{"id":"IMG-RW-L03-U1-LS2-V06","prompt":"Picture for the word 'flippers': a sea turtle swimming with flippers spread"},{"id":"IMG-RW-L03-U1-LS2-V07","prompt":"Picture for the word 'evidence': a magnifying glass over a highlighted sentence"},{"id":"IMG-RW-L03-U1-LS2-01","prompt":"A camel walks on sand and a fennec fox peeks from its burrow."},{"id":"IMG-RW-L03-U1-LS2-02","prompt":"A sea turtle swims over coral with a shark far away."},{"id":"IMG-RW-L03-U1-LS2-03","prompt":"An owl hunts a mouse in a moonlit forest."}],"audio":[{"id":"AUD-RW-L03-U1-LS2-V01","script":"natural. A burrow is a natural home."},{"id":"AUD-RW-L03-U1-LS2-V02","script":"rest. Animals need a safe place to rest."},{"id":"AUD-RW-L03-U1-LS2-V03","script":"wide. Camels have wide feet."},{"id":"AUD-RW-L03-U1-LS2-V04","script":"sink. Wide feet do not sink in the sand."},{"id":"AUD-RW-L03-U1-LS2-V05","script":"salty. Ocean water is salty."},{"id":"AUD-RW-L03-U1-LS2-V06","script":"flippers. Sea turtles use their flippers to swim."},{"id":"AUD-RW-L03-U1-LS2-V07","script":"evidence. Give evidence from the text."},{"id":"AUD-RW-L03-U1-LS2-T1","script":"Every animal needs a home. An animal's natural home is called its habitat. A habitat gives an animal food, water and a safe place to rest. Animals have special body parts that help them survive in their habitats. **Life in the Desert** The desert is very hot in the day and cold at night. Camels can walk for days without drinking water. Their wide feet do not sink in the sand. The fennec fox digs a burrow under the sand to stay cool, and its thick fur keeps it warm at night. **Life in the Ocean** The ocean is full of salty water. Sea turtles swim for many kilometers. Their hard shells protect them from sharks, and their flippers, or flat arms, help them swim. **Life in the Forest** A forest has many trees. Owls build nests in tree holes. They hunt mice at night with their sharp claws. Their soft feathers help them fly without a sound. Every habitat is different, but each animal has what it needs to survive there."},{"id":"AUD-RW-L03-U1-LS2-VID","script":"Adam has two kinds of questions in his research notebook! Homes in the Wild. Every animal needs a home… Right There: What protects sea turtles from sharks? Look – it's right there in one sentence: their hard shells! Think and Search: How does the fennec fox stay comfortable? Search: burrow – stay cool… AND fur – keeps warm! Always show your evidence: The text says…!"}]},{"id":"RW-L03-U1-LS3","title":"Main idea and key details: \"The Desert Fox at Night\"","lesson_type":"strategy_paired_text","objectives":["find the main idea of an article and of a poem and tell it in one sentence","choose three key details that support the main idea and leave out small details","use the Main-Idea Umbrella to show how key details support the main idea"],"objectives_ar":["إيجاد الفكرة الرئيسية لمقال ولقصيدة والتعبير عنها في جملة واحدة.","اختيار ثلاثة تفاصيل رئيسية تدعم الفكرة الرئيسية وترك التفاصيل الصغيرة.","استخدام مظلة الفكرة الرئيسية لبيان كيف تدعم التفاصيل الفكرة."],"success_criteria":["I can say what a text or poem is mostly about.","I can find three key details that support the main idea.","I can tell a key detail from a small, extra detail."],"success_criteria_ar":["أستطيع قول عمّ يتحدث النص أو القصيدة في الغالب.","أستطيع إيجاد ثلاثة تفاصيل رئيسية تدعم الفكرة.","أستطيع التمييز بين التفصيل الرئيسي والتفصيل الصغير الإضافي."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"poem","pos":"noun","ipa":"/ˈpoʊəm/","definition":"writing in short lines, often with rhyme and rhythm","arabic":"قصيدة","example":"We read a poem about a fox.","image_id":"IMG-RW-L03-U1-LS3-V01","audio_id":"AUD-RW-L03-U1-LS3-V01","tier":"core"},{"word":"stanza","pos":"noun","ipa":"/ˈstænzə/","definition":"a group of lines in a poem, like a paragraph","arabic":"مقطع شعري","example":"This poem has five stanzas.","image_id":"IMG-RW-L03-U1-LS3-V02","audio_id":"AUD-RW-L03-U1-LS3-V02","tier":"core"},{"word":"rhyme","pos":"verb / noun","ipa":"/raɪm/","definition":"to end with the same sound (gray – play)","arabic":"يتقافى / قافية","example":"*Drink* rhymes with *think*.","image_id":"IMG-RW-L03-U1-LS3-V03","audio_id":"AUD-RW-L03-U1-LS3-V03","tier":"core"},{"word":"beetle","pos":"noun","ipa":"/ˈbitəl/","definition":"a small insect with a hard, shiny back","arabic":"خنفساء","example":"The fox can hear a beetle walk.","image_id":"IMG-RW-L03-U1-LS3-V04","audio_id":"AUD-RW-L03-U1-LS3-V04","tier":"core"},{"word":"main idea","pos":"noun","ipa":"/meɪn aɪˈdiə/","definition":"what a text is mostly about","arabic":"الفكرة الرئيسية","example":"The main idea is that the fox is made for desert nights.","image_id":"IMG-RW-L03-U1-LS3-V05","audio_id":"AUD-RW-L03-U1-LS3-V05","tier":"core"},{"word":"key detail","pos":"noun","ipa":"/ki ˈditeɪl/","definition":"an important fact that supports the main idea","arabic":"تفصيل رئيسي","example":"Big ears are a key detail.","image_id":"IMG-RW-L03-U1-LS3-V06","audio_id":"AUD-RW-L03-U1-LS3-V06","tier":"core"},{"word":"wise","pos":"adjective","ipa":"/waɪz/","definition":"smart and able to make good choices","arabic":"حكيم","example":"The fox is quick and wise.","image_id":"IMG-RW-L03-U1-LS3-V07","audio_id":"AUD-RW-L03-U1-LS3-V07","tier":"core"}],"explanation":{"text":"The **main idea** is what a text is **mostly about**. It is **bigger** than one detail. **Key details** are the important facts that **support** (hold up) the main idea.\n\nHow to find it: (1) Ask **Who or what is the text about?** (the topic). (2) Ask **What do MOST of the details tell about it?** (3) Put it in **one sentence**. (4) Check: do the key details fit under it like an **umbrella**?\n\n**Poems** have main ideas too. Read every **stanza** and ask what each one tells. Then look for what they **all** have in common.","examples":["Article topic: **animals and their habitats**.","Article main idea: **Animals have special body parts that help them survive in their habitats.**","Article key detail 1: **Camels have wide feet that do not sink in the sand.**","Article key detail 2: **Sea turtles' hard shells protect them from sharks.**","Article key detail 3: **Owls' soft feathers help them fly without a sound.**","Poem topic: **a fennec fox**.","Poem main idea: **The desert fox is well made for life in the desert at night.**","Poem key details: **her giant ears hear tiny animals; her sandy fur hides her; she sleeps in her burrow in the hot day.**","Small, extra detail (not key): *the morning lights the desert red* – it is nice, but it does not support the main idea as much."],"common_errors":["✗ Main idea: 'a fox'. → ✓ Main idea: The desert fox is well made for life in the desert at night. (A topic is one or two words; a main idea is a **sentence**.)","✗ Main idea: 'The fox can hear a beetle walk.' → ✓ That is a **key detail**; the main idea is bigger. (Don't choose one detail as the main idea.)","✗ Choosing the most fun detail as a key detail. → ✓ Choose details that **support** the main idea. (Key = important, not just interesting.)","✗ The poem tell about a fox. → ✓ The poem tells about a fox. (One poem → **tells**.)","✗ Her ears hears a beetle. → ✓ Her ears hear a beetle. (Many ears → **hear**.)","✗ Reading only the first stanza. → ✓ Read **all** the stanzas before you decide. (The main idea comes from the whole text.)"],"arabic":"الفكرة الرئيسية هي ما يتحدث عنه النص في الغالب، وهي أكبر من أي تفصيل واحد. والتفاصيل الرئيسية حقائق مهمة تدعم الفكرة الرئيسية.\n\nلإيجادها: اسأل عمّن أو عمّ يتحدث النص؟ ثم ماذا تخبرنا معظم التفاصيل عنه؟ ثم عبّر عنها في جملة واحدة، وتحقق أن التفاصيل تقع تحتها كالمظلة.\n\nللقصائد أفكار رئيسية أيضًا: اقرأ كل مقطع واسأل ماذا يخبرنا، ثم ابحث عمّا تشترك فيه المقاطع كلها.\n\nالموضوع كلمة أو كلمتان (a fox)، أما الفكرة الرئيسية فجملة كاملة."},"video":{"script":[{"time":"00:00–00:20","narration":"What is it MOSTLY about? That is the main idea!","on_screen":"Main Idea ☂️","visual":"An umbrella opens over small detail raindrops."},{"time":"00:20–00:55","narration":"In Homes in the Wild, the main idea is: Animals have special body parts that help them survive. The details hold it up!","on_screen":"Main idea + 3 key details","visual":"Camel feet, turtle shell and owl feathers become three pillars under a roof."},{"time":"00:55–02:00","narration":"The Desert Fox at Night. When the hot sun goes down to sleep…","on_screen":"(poem, read with rhythm)","visual":"Night falls over dunes; the fennec fox comes out, listens, hides, hunts, then curls up in her burrow at sunrise."},{"time":"02:00–02:35","narration":"Stanza by stanza: ears hear tiny animals… fur hides her… she sleeps in her burrow in the day. What do they all show? She is made for desert nights!","on_screen":"Stanza clues → main idea","visual":"Five stanza boxes each drop one clue into the umbrella."},{"time":"02:35–03:00","narration":"Key detail or extra detail? Key details hold up the main idea!","on_screen":"Key ✔ / Extra ✘","visual":"A key detail holds the umbrella; an extra detail floats away."}],"captions_ar":["عمّ يتحدث النص في الغالب؟ هذه هي الفكرة الرئيسية!","في «بيوت في البرية» الفكرة الرئيسية: للحيوانات أجزاء جسم خاصة تساعدها على البقاء.","ثعلب الصحراء في الليل: عندما تغيب الشمس الحارة…","مقطعًا بعد مقطع: الأذنان تسمعان الحيوانات الصغيرة، والفرو يخفيها، وتنام في جحرها نهارًا. ماذا تُظهر كلها؟ إنها مهيأة لليالي الصحراء!","تفصيل رئيسي أم إضافي؟ التفاصيل الرئيسية تحمل الفكرة الرئيسية!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Poem reader: soft, rhythmic female voice."},"texts":[{"type":"reading","title":"The Desert Fox at Night","body":"When the hot sun goes down to sleep / And sand turns cool and gray, / A little fox with giant ears / Comes out of her burrow to play.\n\nHer ears can hear a beetle walk, / A tiny mouse run past. / Her soft and sandy-colored fur / Can hide her well and fast.\n\nShe does not need a pool or well; / Her food gives her a drink. / She hunts and sniffs and digs and runs / Much faster than you think!\n\nThe owl may fly, the snake may slide, / But she is quick and wise. / She listens with her giant ears / And watches with bright eyes.\n\nWhen morning lights the desert red / And heat comes back once more, / She curls up in her burrow bed / And sleeps behind her sandy door.","word_count":127,"audio_id":"AUD-RW-L03-U1-LS3-T1","id":"TXT-RW-L03-U1-LS3-1","genre":"poetry (original)","role":"paired","difficulty":"350L–500L","glossary":[{"word":"beetle","definition":"a small insect with a hard back","arabic":"خنفساء"},{"word":"well","definition":"a deep hole in the ground with water in it","arabic":"بئر"},{"word":"curls up","definition":"makes her body into a round shape","arabic":"تتكوّر"}]}],"activities":[{"id":"RW-L03-U1-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read *The Desert Fox at Night*. Choose the answer.","instructions_ar":"اقرأ القصيدة واختر الإجابة.","items":[{"q":"When does the fox come out of her burrow?","answer":"when the sun goes down","explanation":"Stanza 1.","explanation_ar":"عند غروب الشمس.","options":["at noon","when the sun goes down","when it rains","in the morning"],"dok":1,"skill":"key details","text_id":"TXT-RW-L03-U1-LS3-1","stage":"controlled"},{"q":"What can the fox's ears hear?","answer":"a beetle walk and a mouse run past","explanation":"Stanza 2.","explanation_ar":"خنفساء تمشي وفأرًا يمر.","options":["the ocean waves","a beetle walk and a mouse run past","a car far away","nothing at all"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What color is the fox's fur?","answer":"sandy-colored","explanation":"Stanza 2.","explanation_ar":"بلون الرمل.","options":["black","white","sandy-colored","bright red"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Where does the fox get water?","answer":"from her food","explanation":"Stanza 3: Her food gives her a drink.","explanation_ar":"من طعامها.","options":["from a pool","from a well","from the ocean","from her food"],"dok":2,"skill":"key details","stage":"controlled"},{"q":"How many stanzas does the poem have?","answer":"five","explanation":"Count the groups of lines.","explanation_ar":"خمسة.","options":["three","four","six","five"],"dok":1,"skill":"poem structure","stage":"controlled"},{"q":"Which word rhymes with *drink* in the poem?","answer":"think","explanation":"drink – think.","explanation_ar":"think.","options":["think","runs","well","food"],"dok":1,"skill":"rhyme","stage":"controlled"}]},{"id":"RW-L03-U1-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Main idea or key detail? Choose.","instructions_ar":"فكرة رئيسية أم تفصيل؟ اختر.","items":[{"q":"What is the TOPIC of the poem?","answer":"a desert fox","explanation":"Who is it about?","explanation_ar":"ثعلب الصحراء.","options":["the ocean","a desert fox","owls in the forest","a camel's feet"],"dok":1,"skill":"topic","stage":"guided"},{"q":"What is the MAIN IDEA of the poem?","answer":"The desert fox is well made for life in the desert at night.","explanation":"It covers all the stanzas.","explanation_ar":"الثعلب مهيأ للحياة الليلية.","options":["The fox can hear a beetle.","The morning sun is red.","Owls can fly.","The desert fox is well made for life in the desert at night."],"dok":2,"skill":"main idea","stage":"guided"},{"q":"Which is a KEY DETAIL that supports the main idea of the poem?","answer":"Her sandy fur can hide her well.","explanation":"Fur helps her survive.","explanation_ar":"الفرو يخفيها.","options":["The morning lights the desert red.","The snake may slide.","The sand turns gray.","Her sandy fur can hide her well."],"dok":2,"skill":"key details","stage":"guided"},{"q":"Which is an EXTRA detail, not a key one?","answer":"And heat comes back once more","explanation":"It describes the morning, not how the fox survives.","explanation_ar":"تفصيل إضافي.","options":["Her ears can hear a beetle walk","Her food gives her a drink","And heat comes back once more","She curls up in her burrow bed"],"dok":2,"skill":"key vs. extra","stage":"guided"},{"q":"Which main idea fits *Homes in the Wild*?","answer":"Animals have special body parts that help them survive in their habitats.","explanation":"It is bigger than one detail.","explanation_ar":"الفكرة الرئيسية للمقال.","options":["Animals have special body parts that help them survive in their habitats.","Camels walk for days.","The ocean is salty.","Owls live in trees."],"dok":2,"skill":"main idea","stage":"guided"},{"q":"Which sentence tells a main idea, not just a topic?","answer":"Desert foxes have many ways to survive the heat.","explanation":"A main idea is a full sentence.","explanation_ar":"جملة كاملة.","options":["desert foxes","the fox","Desert foxes have many ways to survive the heat.","foxes and sand"],"dok":2,"skill":"topic vs. main idea","stage":"guided"}]},{"id":"RW-L03-U1-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Complete the Main-Idea Umbrella for the poem.","instructions_ar":"أكمل مظلة الفكرة الرئيسية للقصيدة.","items":[{"q":"Umbrella – write the main idea in one sentence.","answer":"The desert fox is well made for life in the desert at night.","explanation":"One full sentence.","explanation_ar":"جملة كاملة.","dok":2,"skill":"main idea","stage":"freer"},{"q":"Raindrop 1 – write a key detail about her ears.","answer":"Her giant ears can hear tiny animals like a beetle or a mouse.","explanation":"Ears detail.","explanation_ar":"تفصيل الأذنين.","dok":1,"skill":"key details","stage":"freer"},{"q":"Raindrop 2 – write a key detail about her fur.","answer":"Her sandy-colored fur hides her.","explanation":"Fur detail.","explanation_ar":"تفصيل الفرو.","dok":1,"skill":"key details","stage":"freer"},{"q":"Raindrop 3 – write a key detail about the daytime.","answer":"She sleeps in her cool burrow during the hot day.","explanation":"Daytime detail.","explanation_ar":"تفصيل النهار.","dok":2,"skill":"key details","stage":"freer"}]},{"id":"RW-L03-U1-LS3-A4","type":"open","stage":"production","instructions":"Writing: Think and connect.","instructions_ar":"فكّر واربط.","items":[{"q":"How do the poem and the article BOTH show the fennec fox surviving?","answer":"Both say the fox uses a burrow and has fur that helps it in the desert.","explanation":"Both…","explanation_ar":"كلاهما…","dok":3,"skill":"compare texts","stage":"production"},{"q":"What does the poem tell you that the article does NOT?","answer":"The poem says the fox gets water from her food and has giant ears that hear a beetle.","explanation":"New details.","explanation_ar":"تفاصيل جديدة.","dok":3,"skill":"compare texts","stage":"production"},{"q":"Why does the poet say the fox is *quick and wise*?","answer":"She listens and watches carefully, so she can stay safe from the owl and the snake.","explanation":"Inference + reason.","explanation_ar":"استنتاج + سبب.","dok":3,"skill":"inference","stage":"production"},{"q":"Write the main idea of the poem in your own words.","answer":"The little fox is made to live in the hot desert and comes out at night.","explanation":"Your own words.","explanation_ar":"بكلماتك.","dok":2,"skill":"main idea","stage":"production"}]},{"id":"RW-L03-U1-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"The Desert Fox at Night\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “The Desert Fox at Night”.","answer":"127 words","title":"The Desert Fox at Night","body":"When the hot sun goes down to sleep / And sand turns cool and gray, / A little fox with giant ears / Comes out of her burrow to play.\n\nHer ears can hear a beetle walk, / A tiny mouse run past. / Her soft and sandy-colored fur / Can hide her well and fast.\n\nShe does not need a pool or well; / Her food gives her a drink. / She hunts and sniffs and digs and runs / Much faster than you think!\n\nThe owl may fly, the snake may slide, / But she is quick and wise. / She listens with her giant ears / And watches with bright eyes.\n\nWhen morning lights the desert red / And heat comes back once more, / She curls up in her burrow bed / And sleeps behind her sandy door.","words":127,"limit":123}],"time_limit_sec":123},{"id":"RW-L03-U1-LS3-ORG","type":"organizer","organizer":"Main-Idea Umbrella","instructions":"Organizer: Write the main idea on the umbrella and one key detail on each raindrop under it.","items":[{"q":"Umbrella – main idea (one sentence)","answer":"The desert fox is well made for life in the desert at night."},{"q":"Raindrop 1 – key detail","answer":"Her giant ears can hear tiny animals like a beetle or a mouse."},{"q":"Raindrop 2 – key detail","answer":"Her sandy-colored fur hides her."},{"q":"Raindrop 3 – key detail","answer":"She sleeps in her cool burrow during the hot day."}]}],"game":{"name":"Hold Up the Umbrella","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Umbrella builder: a main idea appears on an umbrella; detail drops fall; the child catches three key details and lets extra details fall. A full umbrella keeps the fox dry in a desert rainstorm.","Each team gets one umbrella card and eight detail cards.","Teams choose the three best key details and stick them under the umbrella.","Teams read the main idea and the three details aloud.","Other teams check: do all details support the main idea?","Correct umbrella = 3 points; good reasons = bonus point."],"data":[]},"exit_quiz":[{"q":"When we read an article or a poem, the main idea is ___.","answer":"what a text is mostly about","explanation":"Main idea = mostly about.","explanation_ar":"ما يتحدث عنه النص في الغالب.","options":["the first word","one small detail","the title only","what a text is mostly about"],"dok":1,"skill":"main idea"},{"q":"Key details ___ the main idea.","answer":"support","explanation":"Details hold up the main idea.","explanation_ar":"تدعم.","options":["replace","hide","support","end"],"dok":1,"skill":"key details"},{"q":"A group of lines in a poem is a ___.","answer":"stanza","explanation":"Stanza = group of lines.","explanation_ar":"مقطع.","options":["heading","stanza","caption","burrow"],"dok":1,"skill":"poem structure"},{"q":"Which words rhyme in stanza 1?","answer":"gray – play","explanation":"gray/play end with the same sound.","explanation_ar":"gray – play.","options":["sun – ears","gray – play","sleep – fox","cool – little"],"dok":1,"skill":"rhyme"},{"q":"*She is quick and wise.* *Wise* means ___.","answer":"smart and able to make good choices","explanation":"Wise = smart, good choices.","explanation_ar":"حكيمة.","options":["smart and able to make good choices","very slow","very loud","sleepy"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence is a TOPIC, not a main idea?","answer":"the fennec fox","explanation":"A topic is a word or phrase.","explanation_ar":"الموضوع.","options":["The fennec fox is made for desert nights.","Animals survive with special body parts.","Desert animals adapt to heat and cold.","the fennec fox"],"dok":2,"skill":"topic vs. main idea"},{"q":"Which detail BEST supports *The fox is good at hunting at night*?","answer":"Her ears can hear a beetle walk.","explanation":"Hearing helps her hunt.","explanation_ar":"سمعها يساعدها على الصيد.","options":["Her ears can hear a beetle walk.","The morning lights the desert red.","Heat comes back once more.","The sand turns gray."],"dok":2,"skill":"key details"},{"q":"Why does the fox sleep in her burrow in the day?","answer":"to stay cool when the desert is hot","explanation":"The burrow is cool.","explanation_ar":"لتبقى باردة.","options":["because she is lazy","to hunt the owl","to stay cool when the desert is hot","because it is raining"],"dok":2,"skill":"inference"},{"q":"How are the article and the poem alike?","answer":"Both show that animals have ways to survive in their habitats.","explanation":"They share a main idea about survival.","explanation_ar":"كلاهما عن بقاء الحيوانات.","options":["Both show that animals have ways to survive in their habitats.","Both are stories with a problem.","Both are about the ocean.","Both have rhyming lines."],"dok":3,"skill":"compare texts"},{"q":"Why did the poet write *The Desert Fox at Night* as a poem, not an article?","answer":"to share facts in a fun way with rhythm and rhyme","explanation":"Poems use rhythm and rhyme.","explanation_ar":"لعرض الحقائق بطريقة ممتعة.","options":["to give headings","to share facts in a fun way with rhythm and rhyme","to list numbers","to teach a recipe"],"dok":3,"skill":"author's purpose"}],"images":[{"id":"IMG-RW-L03-U1-LS3-V01","prompt":"Picture for the word 'poem': a page with short lines in stanzas"},{"id":"IMG-RW-L03-U1-LS3-V02","prompt":"Picture for the word 'stanza': a poem with stanzas boxed"},{"id":"IMG-RW-L03-U1-LS3-V03","prompt":"Picture for the word 'rhyme': two word cards with matching ending sounds"},{"id":"IMG-RW-L03-U1-LS3-V04","prompt":"Picture for the word 'beetle': a black beetle on sand"},{"id":"IMG-RW-L03-U1-LS3-V05","prompt":"Picture for the word 'main idea': an umbrella over smaller ideas"},{"id":"IMG-RW-L03-U1-LS3-V06","prompt":"Picture for the word 'key detail': pillars holding up a roof"},{"id":"IMG-RW-L03-U1-LS3-V07","prompt":"Picture for the word 'wise': a fox looking carefully around a rock"},{"id":"IMG-RW-L03-U1-LS3-01","prompt":"A fennec fox listens on a moonlit dune."},{"id":"IMG-RW-L03-U1-LS3-02","prompt":"The fox sleeps curled up in her burrow at sunrise."},{"id":"IMG-RW-L03-U1-LS3-03","prompt":"An umbrella organizer for main idea and key details."}],"audio":[{"id":"AUD-RW-L03-U1-LS3-V01","script":"poem. We read a poem about a fox."},{"id":"AUD-RW-L03-U1-LS3-V02","script":"stanza. This poem has five stanzas."},{"id":"AUD-RW-L03-U1-LS3-V03","script":"rhyme. *Drink* rhymes with *think*."},{"id":"AUD-RW-L03-U1-LS3-V04","script":"beetle. The fox can hear a beetle walk."},{"id":"AUD-RW-L03-U1-LS3-V05","script":"main idea. The main idea is that the fox is made for desert nights."},{"id":"AUD-RW-L03-U1-LS3-V06","script":"key detail. Big ears are a key detail."},{"id":"AUD-RW-L03-U1-LS3-V07","script":"wise. The fox is quick and wise."},{"id":"AUD-RW-L03-U1-LS3-T1","script":"When the hot sun goes down to sleep / And sand turns cool and gray, / A little fox with giant ears / Comes out of her burrow to play. Her ears can hear a beetle walk, / A tiny mouse run past. / Her soft and sandy-colored fur / Can hide her well and fast. She does not need a pool or well; / Her food gives her a drink. / She hunts and sniffs and digs and runs / Much faster than you think! The owl may fly, the snake may slide, / But she is quick and wise. / She listens with her giant ears / And watches with bright eyes. When morning lights the desert red / And heat comes back once more, / She curls up in her burrow bed / And sleeps behind her sandy door."},{"id":"AUD-RW-L03-U1-LS3-VID","script":"What is it MOSTLY about? That is the main idea! In Homes in the Wild, the main idea is: Animals have special body parts that help them survive. The details hold it up! The Desert Fox at Night. When the hot sun goes down to sleep… Stanza by stanza: ears hear tiny animals… fur hides her… she sleeps in her burrow in the day. What do they all show? She is made for desert nights! Key detail or extra detail? Key details hold up the main idea!"}]},{"id":"RW-L03-U1-LS4","title":"Writing Skill: Paragraph: topic sentence + 3 details","lesson_type":"writing_skill","objectives":["write a paragraph with a topic sentence, three key details and a closing sentence","add an explaining sentence to a detail (because…, This helps…)","join details with linking words: First, Also, In addition, For all these reasons"],"objectives_ar":["كتابة فقرة فيها جملة رئيسية وثلاثة تفاصيل رئيسية وجملة ختامية.","إضافة جملة شارحة إلى التفصيل.","ربط التفاصيل بكلمات الربط."],"success_criteria":["I can write a topic sentence that tells the main idea.","I can write three details that support my topic sentence.","I can write a closing sentence in new words."],"success_criteria_ar":["أستطيع كتابة جملة رئيسية تخبر بالفكرة الرئيسية.","أستطيع كتابة ثلاثة تفاصيل تدعم جملتي الرئيسية.","أستطيع كتابة جملة ختامية بكلمات جديدة."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"expert","pos":"noun","ipa":"/ˈɛkspərt/","definition":"someone who is very good at something or knows a lot about it","arabic":"خبير","example":"The camel is a desert expert.","image_id":"IMG-RW-L03-U1-LS4-V01","audio_id":"AUD-RW-L03-U1-LS4-V01","tier":"core"},{"word":"hump","pos":"noun","ipa":"/hʌmp/","definition":"the round part on a camel's back","arabic":"سنام","example":"A camel stores fat in its hump.","image_id":"IMG-RW-L03-U1-LS4-V02","audio_id":"AUD-RW-L03-U1-LS4-V02","tier":"core"},{"word":"energy","pos":"noun","ipa":"/ˈɛnərdʒi/","definition":"the power to move and work","arabic":"طاقة","example":"Food gives us energy.","image_id":"IMG-RW-L03-U1-LS4-V03","audio_id":"AUD-RW-L03-U1-LS4-V03","tier":"core"},{"word":"eyelashes","pos":"noun","ipa":"/ˈaɪlæʃɪz/","definition":"the short hairs on the edge of your eyelids","arabic":"رموش","example":"Long eyelashes keep sand out of the camel's eyes.","image_id":"IMG-RW-L03-U1-LS4-V04","audio_id":"AUD-RW-L03-U1-LS4-V04","tier":"core"},{"word":"closing sentence","pos":"noun","ipa":"/ˈkloʊzɪŋ ˈsɛntəns/","definition":"the last sentence of a paragraph that sums up the main idea","arabic":"الجملة الختامية","example":"My closing sentence repeats my main idea in new words.","image_id":"IMG-RW-L03-U1-LS4-V05","audio_id":"AUD-RW-L03-U1-LS4-V05","tier":"core"},{"word":"in addition","pos":"phrase","ipa":"/ɪn əˈdɪʃən/","definition":"a linking phrase that adds one more idea","arabic":"بالإضافة إلى ذلك","example":"In addition, camels have wide feet.","image_id":"IMG-RW-L03-U1-LS4-V06","audio_id":"AUD-RW-L03-U1-LS4-V06","tier":"core"},{"word":"store","pos":"verb","ipa":"/stɔr/","definition":"to keep something to use later","arabic":"يخزّن","example":"Squirrels store nuts for winter.","image_id":"IMG-RW-L03-U1-LS4-V07","audio_id":"AUD-RW-L03-U1-LS4-V07","tier":"core"}],"explanation":{"text":"A strong **informative paragraph** has four parts: a **topic sentence**, **three key details**, and a **closing sentence**.\n\nEach **detail** is a **fact** that supports the topic sentence. Make a detail stronger with an **explaining sentence**: *Camels store fat in their humps. **The fat gives them energy when there is no food.***\n\nUse **linking words** to move from one detail to the next: **First,** … **Also,** … **In addition,** … and to close: **For all these reasons,** … / **That is why** … The closing says the main idea again **in new words**.","examples":["Topic sentence: **Camels have many ways to survive in the hot, dry desert.**","Detail 1: **First, a camel can walk for days without drinking water.**","Explaining sentence: **The fat in its hump gives it energy when there is no food.**","Detail 2: **Also, camels have long eyelashes that protect their eyes from blowing sand.**","Detail 3: **In addition, their wide, flat feet help them walk on the sand without sinking.**","Closing: **For all these reasons, the camel is a true desert expert.**","Another topic sentence: **Sea turtles are made for life in the ocean.**","Another closing: **That is why the owl is the queen of the night forest.**","Not a closing (too short, copies the topic): *Camels have many ways to survive in the desert.* → say it in **new words**."],"common_errors":["✗ Writing only two details. → ✓ Write **three** key details. (Level 3 paragraphs need three details.)","✗ Copying the topic sentence as the closing. → ✓ For all these reasons, the camel is a true desert expert. (Use **new words** in the closing.)","✗ Also camels have long eyelashes. → ✓ Also, camels have long eyelashes. (Comma after linking words at the start.)","✗ In addition camels has wide feet. → ✓ In addition, camels have wide feet. (Comma + **have** (many camels).)","✗ A detail about a different animal (Lions have manes.) → ✓ Keep every detail about camels. (Every detail must support the topic.)","✗ The camel store fat in it's hump. → ✓ The camel stores fat in its hump. (**stores**; **its** (no apostrophe) = belongs to it.)"],"arabic":"الفقرة المعلوماتية القوية لها أربعة أجزاء: جملة رئيسية، وثلاثة تفاصيل رئيسية، وجملة ختامية.\n\nكل تفصيل حقيقة تدعم الجملة الرئيسية، ويمكن تقويته بجملة شارحة: The fat gives them energy when there is no food.\n\nاستخدم كلمات الربط: First, Also, In addition، وللختام: For all these reasons أو That is why.\n\nالجملة الختامية تعيد الفكرة الرئيسية بكلمات جديدة، ولا تنسخ الجملة الرئيسية."},"video":{"script":[{"time":"00:00–00:15","narration":"Adam wrote a paragraph about his favorite desert animal!","on_screen":"Camels Are Desert Experts","visual":"Adam next to a camel with a notebook."},{"time":"00:15–01:00","narration":"Camels have many ways to survive in the hot, dry desert. First, a camel can walk for days…","on_screen":"(model paragraph)","visual":"The paragraph builds line by line on a hamburger organizer."},{"time":"01:00–01:40","narration":"Topic sentence on top. Three details in the middle. A closing at the bottom!","on_screen":"Topic + 3 details + closing","visual":"Hamburger layers labelled detail 1, 2, 3."},{"time":"01:40–02:20","narration":"Make a detail stronger: add an explaining sentence. The fat gives the camel energy!","on_screen":"Fact + explain","visual":"A detail layer gets a second, thinner layer: 'explain'."},{"time":"02:20–02:55","narration":"Link your details: First… Also… In addition… For all these reasons!","on_screen":"First · Also · In addition · For all these reasons","visual":"Linking words click together like train couplings."}],"captions_ar":["كتب آدم فقرة عن حيوانه الصحراوي المفضل!","للجمال طرق كثيرة للبقاء في الصحراء الحارة الجافة. أولًا: يستطيع الجمل المشي أيامًا…","الجملة الرئيسية في الأعلى، وثلاثة تفاصيل في الوسط، والخاتمة في الأسفل!","قوِّ التفصيل بجملة شارحة: الدهن يعطي الجمل طاقة!","اربط تفاصيلك: First… Also… In addition… For all these reasons!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Adam reads his paragraph like a proud researcher."},"texts":[{"type":"model","title":"Camels Are Desert Experts (by Adam)","body":"Camels have many ways to survive in the hot, dry desert. First, a camel can walk for days without drinking water because it stores fat in its hump. The fat gives the camel energy when there is no food. Also, camels have long eyelashes that protect their eyes from blowing sand. In addition, their wide, flat feet help them walk on the sand without sinking. For all these reasons, the camel is a true desert expert.","word_count":76,"audio_id":"AUD-RW-L03-U1-LS4-T1","id":"TXT-RW-L03-U1-LS4-1","genre":"model text","role":"model","difficulty":"350L–500L","glossary":[],"annotations":["**Topic sentence:** *Camels have many ways to survive in the hot, dry desert.* – it tells the main idea of the whole paragraph.","**Detail 1 + explanation:** *First, … stores fat in its hump. The fat gives the camel energy…* – one fact, then one sentence that explains it.","**Detail 2:** *Also, camels have long eyelashes…* – a new fact with a linking word (Also).","**Detail 3:** *In addition, their wide, flat feet…* – the third key detail.","**Closing sentence:** *For all these reasons, the camel is a true desert expert.* – says the main idea again in new words.","**Linking words** (First, Also, In addition, For all these reasons) join the details smoothly."]}],"activities":[{"id":"RW-L03-U1-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Which sentence is the topic sentence of Adam's paragraph?","answer":"Camels have many ways to survive in the hot, dry desert.","explanation":"It tells the main idea.","explanation_ar":"الجملة الرئيسية.","options":["First, a camel can walk for days without drinking water.","In addition, their wide, flat feet help them walk on sand.","For all these reasons, the camel is a true desert expert.","Camels have many ways to survive in the hot, dry desert."],"dok":1,"skill":"topic sentence","stage":"controlled"},{"q":"How many key details does Adam give?","answer":"three","explanation":"First, Also, In addition.","explanation_ar":"ثلاثة.","options":["one","three","two","five"],"dok":1,"skill":"paragraph structure","stage":"controlled"},{"q":"Which sentence is Adam's closing sentence?","answer":"For all these reasons, the camel is a true desert expert.","explanation":"The last sentence sums up.","explanation_ar":"الجملة الختامية.","options":["Camels have many ways to survive.","The fat gives the camel energy.","For all these reasons, the camel is a true desert expert.","Also, camels have long eyelashes."],"dok":1,"skill":"closing","stage":"controlled"},{"q":"What does a camel store in its hump?","answer":"fat","explanation":"Model text.","explanation_ar":"الدهن.","options":["water","sand","fat","eyelashes"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Which linking phrase ADDS one more idea?","answer":"In addition,","explanation":"In addition = one more.","explanation_ar":"In addition.","options":["In addition,","For all these reasons,","First,","But"],"dok":1,"skill":"linking words","stage":"controlled"},{"q":"*The fat gives the camel energy.* This sentence ___ detail 1.","answer":"explains","explanation":"It tells more about the hump.","explanation_ar":"يشرح.","options":["explains","replaces","ends","repeats the title of"],"dok":2,"skill":"explaining sentences","stage":"controlled"}]},{"id":"RW-L03-U1-LS4-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Build a paragraph about sea turtles. Choose.","instructions_ar":"ابنِ فقرة عن السلاحف البحرية. اختر.","items":[{"q":"Which is the best topic sentence for a sea-turtle paragraph?","answer":"Sea turtles are made for life in the ocean.","explanation":"It tells the main idea.","explanation_ar":"جملة رئيسية مناسبة.","options":["Sea turtles.","I saw a turtle once.","Their flippers are flat.","Sea turtles are made for life in the ocean."],"dok":2,"skill":"topic sentence","stage":"guided"},{"q":"Which detail supports *Sea turtles are made for life in the ocean*?","answer":"Their flippers help them swim long distances.","explanation":"About turtles in the ocean.","explanation_ar":"تفصيل داعم.","options":["Their flippers help them swim long distances.","Camels have humps.","Owls hunt at night.","The desert is dry."],"dok":1,"skill":"relevant details","stage":"guided"},{"q":"Which explaining sentence fits *Sea turtles have hard shells*?","answer":"The shell protects them from sharks.","explanation":"It explains how the shell helps.","explanation_ar":"يشرح فائدة الصدفة.","options":["The shell is a kind of food.","The shell protects them from sharks.","Turtles like the desert.","Shells are always green."],"dok":2,"skill":"explaining sentences","stage":"guided"},{"q":"Which detail does NOT belong in a sea-turtle paragraph?","answer":"Camels have long eyelashes.","explanation":"Camels are not sea turtles.","explanation_ar":"لا ينتمي.","options":["Sea turtles can hold their breath for a long time.","Camels have long eyelashes.","Mother turtles lay eggs on the beach.","Their flippers help them swim."],"dok":1,"skill":"relevant details","stage":"guided"},{"q":"Which closing sentence is best for the sea-turtle paragraph?","answer":"That is why sea turtles are true ocean travelers.","explanation":"New words for the main idea.","explanation_ar":"خاتمة بكلمات جديدة.","options":["Sea turtles are made for life in the ocean.","I like pizza.","First, sea turtles swim.","That is why sea turtles are true ocean travelers."],"dok":2,"skill":"closing","stage":"guided"},{"q":"Which sentence uses a linking word correctly?","answer":"Also, sea turtles can hold their breath for a long time.","explanation":"Comma after Also; can + base verb.","explanation_ar":"صحيحة.","options":["Also sea turtles, can hold their breath.","Sea turtles also, can hold.","Also, sea turtles can hold their breath for a long time.","Also, sea turtles can holds their breath."],"dok":2,"skill":"linking words","stage":"guided"}]},{"id":"RW-L03-U1-LS4-A3","type":"sequence","stage":"freer","instructions":"Put in order: Put the paragraph in order.","instructions_ar":"رتّب الفقرة.","items":[{"q":"Order the owl paragraph.","answer":"Owls are made for hunting at night. → First, they have big eyes that see in the dark. → Also, their soft feathers make no sound. → In addition, their sharp claws catch mice. → That is why owls are great night hunters.","explanation":"Topic → 3 details → closing.","explanation_ar":"رئيسية ← 3 تفاصيل ← خاتمة.","stage":"freer","parts":["Owls are made for hunting at night.","Also, their soft feathers make no sound.","First, they have big eyes that see in the dark.","In addition, their sharp claws catch mice.","That is why owls are great night hunters."],"target":["Owls are made for hunting at night.","First, they have big eyes that see in the dark.","Also, their soft feathers make no sound.","In addition, their sharp claws catch mice.","That is why owls are great night hunters."]},{"q":"Build detail 3 for a camel paragraph.","answer":"In addition, → their wide feet → do not sink → in the sand.","explanation":"Linking phrase + comma + detail.","explanation_ar":"رابط + فاصلة + تفصيل.","stage":"freer","parts":["do not sink","in the sand.","their wide feet","In addition,"],"target":["In addition,","their wide feet","do not sink","in the sand."]},{"q":"Build a closing about the fennec fox.","answer":"For all these reasons, → the fox → is a desert → survivor.","explanation":"Closing phrase + new words.","explanation_ar":"عبارة ختام + كلمات جديدة.","stage":"freer","parts":["is a desert","For all these reasons,","the fox","survivor."],"target":["For all these reasons,","the fox","is a desert","survivor."]},{"q":"Build a detail about sea turtles.","answer":"Their flippers help them swim long distances.","explanation":"A key detail about turtles.","explanation_ar":"تفصيل رئيسي.","stage":"freer","parts":["swim long","distances.","help them","Their flippers"],"target":["Their flippers","help them","swim long","distances."]}]},{"id":"RW-L03-U1-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write parts of a paragraph.","instructions_ar":"اكتب أجزاء الفقرة.","items":[{"q":"Write a topic sentence about the fennec fox.","answer":"The fennec fox has many ways to survive in the desert.","explanation":"Main idea sentence.","explanation_ar":"جملة الفكرة الرئيسية.","dok":2,"skill":"topic sentence","stage":"production"},{"q":"Write three details about the fennec fox with First, Also and In addition.","answer":"First, its giant ears hear tiny animals. Also, its sandy fur hides it. In addition, it sleeps in a cool burrow in the day.","explanation":"Three linked details.","explanation_ar":"ثلاثة تفاصيل مربوطة.","dok":2,"skill":"details","stage":"production"},{"q":"Add an explaining sentence to one of your details.","answer":"Its giant ears also let heat out, so the fox stays cool.","explanation":"Explain the detail.","explanation_ar":"اشرح التفصيل.","dok":3,"skill":"explaining sentences","stage":"production"},{"q":"Write a closing sentence in new words.","answer":"For all these reasons, the fennec fox is a small desert hero.","explanation":"Main idea in new words.","explanation_ar":"الفكرة بكلمات جديدة.","dok":3,"skill":"closing","stage":"production"}]}],"game":{"name":"Build the Table","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Table builder: a table top with a topic sentence appears; the child drags three correct detail legs under it and a closing base. A wrong leg makes the table wobble and fall.","Teams get pieces for four animal paragraphs mixed together.","Teams build each table: one top, three legs, one base.","Legs that do not belong go in the 'wobbly box'.","Teams read one finished paragraph aloud with linking words.","Each correct table = 3 points; a strong reading = bonus point."],"data":[]},"exit_quiz":[{"q":"What are the four parts of a strong paragraph?","answer":"topic sentence, three details, closing sentence","explanation":"Four parts of a paragraph.","explanation_ar":"الأجزاء الأربعة.","options":["title, picture, caption, glossary","topic sentence, three details, closing sentence","beginning, problem, solution, lesson","question, answer, evidence, map"],"dok":1,"skill":"paragraph structure"},{"q":"Where does the topic sentence usually go?","answer":"at the beginning","explanation":"It comes first.","explanation_ar":"في البداية.","options":["at the beginning","at the end","in the middle","in the title"],"dok":1,"skill":"topic sentence"},{"q":"Which phrase is a good way to start a closing sentence?","answer":"For all these reasons,","explanation":"It signals the end.","explanation_ar":"For all these reasons.","options":["First,","Also,","Once upon a time,","For all these reasons,"],"dok":1,"skill":"linking words"},{"q":"*A camel stores fat in its hump.* *Store* means ___.","answer":"keep to use later","explanation":"Store = keep for later.","explanation_ar":"يخزّن.","options":["throw away","eat right now","sell","keep to use later"],"dok":1,"skill":"vocabulary"},{"q":"Which detail about camels has the comma in the right place?","answer":"Also, camels have long eyelashes.","explanation":"Comma after Also.","explanation_ar":"الفاصلة بعد Also.","options":["Also camels, have long eyelashes.","Also camels have, long eyelashes.","Also, camels have long eyelashes.","Also camels have long, eyelashes."],"dok":2,"skill":"punctuation"},{"q":"Topic sentence: *Owls are made for hunting at night.* Which detail belongs?","answer":"Owls have big eyes that see in the dark.","explanation":"About owls hunting at night.","explanation_ar":"ينتمي.","options":["Owls have big eyes that see in the dark.","Camels store fat.","Turtles lay eggs on the beach.","Foxes live in burrows."],"dok":2,"skill":"relevant details"},{"q":"Why should a closing sentence use NEW words?","answer":"so it sums up the main idea without copying the topic sentence","explanation":"Restate, don't copy.","explanation_ar":"حتى لا تنسخ الجملة الرئيسية.","options":["so the paragraph is shorter","so it can start a new topic","so it has no meaning","so it sums up the main idea without copying the topic sentence"],"dok":2,"skill":"closing"},{"q":"What does an explaining sentence do?","answer":"It tells more about a detail.","explanation":"Explain = tell more.","explanation_ar":"يخبر بالمزيد عن التفصيل.","options":["It starts a new topic.","It is the title.","It tells more about a detail.","It asks a question."],"dok":2,"skill":"explaining sentences"},{"q":"Which is the strongest detail for a paragraph about camels?","answer":"Camels can close their noses to keep sand out during sandstorms.","explanation":"Specific and supports survival.","explanation_ar":"تفصيل محدد قوي.","options":["Camels are nice.","I like camels.","Camels can close their noses to keep sand out during sandstorms.","Camels are animals."],"dok":3,"skill":"evaluate details"},{"q":"A partner's paragraph has a topic sentence and a closing but only ONE detail. What should the partner do?","answer":"add two more details that support the topic sentence","explanation":"Three details are needed.","explanation_ar":"يضيف تفصيلين.","options":["remove the closing","add two more details that support the topic sentence","copy the topic sentence three times","change the animal"],"dok":3,"skill":"revising"}],"images":[{"id":"IMG-RW-L03-U1-LS4-V01","prompt":"Picture for the word 'expert': a camel wearing a tiny graduation cap"},{"id":"IMG-RW-L03-U1-LS4-V02","prompt":"Picture for the word 'hump': a camel's hump in side view"},{"id":"IMG-RW-L03-U1-LS4-V03","prompt":"Picture for the word 'energy': a battery icon filling up"},{"id":"IMG-RW-L03-U1-LS4-V04","prompt":"Picture for the word 'eyelashes': a close-up of a camel's long eyelashes"},{"id":"IMG-RW-L03-U1-LS4-V05","prompt":"Picture for the word 'closing sentence': the bottom bun of a burger labelled 'closing'"},{"id":"IMG-RW-L03-U1-LS4-V06","prompt":"Picture for the word 'in addition': a plus sign joining two ideas"},{"id":"IMG-RW-L03-U1-LS4-V07","prompt":"Picture for the word 'store': a squirrel putting nuts in a tree hole"},{"id":"IMG-RW-L03-U1-LS4-01","prompt":"A camel with labels for its hump, eyelashes and feet."},{"id":"IMG-RW-L03-U1-LS4-02","prompt":"A table showing a topic sentence held up by three details."},{"id":"IMG-RW-L03-U1-LS4-03","prompt":"A train of linking words."}],"audio":[{"id":"AUD-RW-L03-U1-LS4-V01","script":"expert. The camel is a desert expert."},{"id":"AUD-RW-L03-U1-LS4-V02","script":"hump. A camel stores fat in its hump."},{"id":"AUD-RW-L03-U1-LS4-V03","script":"energy. Food gives us energy."},{"id":"AUD-RW-L03-U1-LS4-V04","script":"eyelashes. Long eyelashes keep sand out of the camel's eyes."},{"id":"AUD-RW-L03-U1-LS4-V05","script":"closing sentence. My closing sentence repeats my main idea in new words."},{"id":"AUD-RW-L03-U1-LS4-V06","script":"in addition. In addition, camels have wide feet."},{"id":"AUD-RW-L03-U1-LS4-V07","script":"store. Squirrels store nuts for winter."},{"id":"AUD-RW-L03-U1-LS4-T1","script":"Camels have many ways to survive in the hot, dry desert. First, a camel can walk for days without drinking water because it stores fat in its hump. The fat gives the camel energy when there is no food. Also, camels have long eyelashes that protect their eyes from blowing sand. In addition, their wide, flat feet help them walk on the sand without sinking. For all these reasons, the camel is a true desert expert."},{"id":"AUD-RW-L03-U1-LS4-VID","script":"Adam wrote a paragraph about his favorite desert animal! Camels have many ways to survive in the hot, dry desert. First, a camel can walk for days… Topic sentence on top. Three details in the middle. A closing at the bottom! Make a detail stronger: add an explaining sentence. The fat gives the camel energy! Link your details: First… Also… In addition… For all these reasons!"}]},{"id":"RW-L03-U1-LS5","title":"Writing Workshop: An informative paragraph about one animal and its habitat","lesson_type":"writing_workshop","objectives":["research and plan an informative paragraph about one animal and its habitat","write 6–8 sentences: topic sentence, three key details with explanations, linking words and a closing","revise with a partner, edit with a checklist and publish an 'Animal Fact Card'"],"objectives_ar":["البحث والتخطيط لفقرة معلوماتية عن حيوان واحد وبيئته.","كتابة 6–8 جمل: جملة رئيسية، وثلاثة تفاصيل مع شرح، وكلمات ربط، وجملة ختامية.","التحسين مع زميل والتدقيق بقائمة تحقق ونشر «بطاقة حقائق عن حيوان»."],"success_criteria":["I can plan a topic sentence, three details and a closing.","I can use unit words (habitat, survive, protect…) correctly.","I can check punctuation after linking words and subject–verb agreement."],"success_criteria_ar":["أستطيع التخطيط لجملة رئيسية وثلاثة تفاصيل وخاتمة.","أستطيع استخدام كلمات الوحدة بشكل صحيح.","أستطيع تدقيق الفواصل بعد كلمات الربط وتوافق الفعل مع الفاعل."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"informative","pos":"adjective","ipa":"/ɪnˈfɔrmətɪv/","definition":"giving facts and information","arabic":"معلوماتي","example":"An informative paragraph teaches the reader facts.","image_id":"IMG-RW-L03-U1-LS5-V01","audio_id":"AUD-RW-L03-U1-LS5-V01","tier":"core"},{"word":"fact","pos":"noun","ipa":"/fækt/","definition":"something that is true and can be checked","arabic":"حقيقة","example":"It is a fact that turtles have shells.","image_id":"IMG-RW-L03-U1-LS5-V02","audio_id":"AUD-RW-L03-U1-LS5-V02","tier":"core"},{"word":"research","pos":"verb / noun","ipa":"/rɪˈsɝtʃ/","definition":"to look for facts in books or trusted websites","arabic":"يبحث / بحث","example":"I research my animal in the library.","image_id":"IMG-RW-L03-U1-LS5-V03","audio_id":"AUD-RW-L03-U1-LS5-V03","tier":"core"},{"word":"coral reef","pos":"noun","ipa":"/ˈkɔrəl rif/","definition":"a colorful underwater place made by tiny sea animals","arabic":"شعاب مرجانية","example":"Many fish live on the coral reef.","image_id":"IMG-RW-L03-U1-LS5-V04","audio_id":"AUD-RW-L03-U1-LS5-V04","tier":"core"},{"word":"lay eggs","pos":"verb","ipa":"/leɪ ɛɡz/","definition":"to push eggs out of the body (birds, turtles, fish)","arabic":"يبيض","example":"Turtles lay eggs on the beach.","image_id":"IMG-RW-L03-U1-LS5-V05","audio_id":"AUD-RW-L03-U1-LS5-V05","tier":"core"},{"word":"seagrass","pos":"noun","ipa":"/ˈsiɡræs/","definition":"a green plant that grows under the sea","arabic":"أعشاب بحرية","example":"Green turtles eat seagrass.","image_id":"IMG-RW-L03-U1-LS5-V06","audio_id":"AUD-RW-L03-U1-LS5-V06","tier":"core"},{"word":"source","pos":"noun","ipa":"/sɔrs/","definition":"where you get information (a book, a website, an expert)","arabic":"مصدر","example":"Write the source of your facts.","image_id":"IMG-RW-L03-U1-LS5-V07","audio_id":"AUD-RW-L03-U1-LS5-V07","tier":"core"}],"explanation":{"text":"An **informative paragraph** teaches the reader **facts**. Choose **one animal** and **one habitat**.\n\n**Research** first: find 3 key facts in a library book or a trusted website and write the **source**. Then plan with the **Hamburger Plan**: topic sentence → 3 details (+ explaining sentences) → closing.\n\nUse **unit words** (habitat, survive, protect, hunt, burrow…), **linking words** (First, Also, In addition, For all these reasons) and a **definition clue** for any hard word.","examples":["Topic sentence: **The green sea turtle is made for life in the warm Red Sea.**","Detail 1: **First, it has strong flippers, or flat arms, that help it swim long distances.**","Explain: **It can swim hundreds of kilometers to find food.**","Detail 2: **Also, its hard shell protects it from sharks.**","Detail 3: **In addition, it eats seagrass, a green plant that grows under the sea.**","Explain: **This food gives it the energy to keep swimming.**","Closing: **For all these reasons, the green sea turtle can survive in its ocean habitat.**","Source line: **Source: \"Ocean Animals\" (school library book).**","Other animal ideas: the Arabian oryx (desert), the dolphin (ocean), the woodpecker (forest), the camel (desert)."],"common_errors":["✗ Writing about three animals in one paragraph. → ✓ Write about **one** animal. (One paragraph = one topic.)","✗ Copying sentences from a book. → ✓ Take notes, then write the facts in **your own words**. (Copying is not your writing.)","✗ The turtle have a hard shell. → ✓ The turtle has a hard shell. (One turtle → **has**.)","✗ Also it eats seagrass. → ✓ Also, it eats seagrass. (Comma after **Also**.)","✗ I think turtles are cute. (opinion as a fact) → ✓ Turtles can hold their breath for hours. (fact) (Informative = **facts**, not opinions.)","✗ (no closing) → ✓ For all these reasons, the green sea turtle can survive in its ocean habitat. (End with a closing sentence.)"],"arabic":"الفقرة المعلوماتية تعلّم القارئ حقائق. اختر حيوانًا واحدًا وبيئة واحدة.\n\nابحث أولًا: جِد 3 حقائق رئيسية في كتاب من المكتبة أو موقع موثوق، واكتب المصدر، ثم خطط بخطة الهامبرغر.\n\nاستخدم كلمات الوحدة وكلمات الربط ودليل التعريف لأي كلمة صعبة.\n\nاكتب الحقائق بكلماتك أنت ولا تنسخ الجمل من الكتاب، وتجنّب الآراء الشخصية في الفقرة المعلوماتية."},"video":{"script":[{"time":"00:00–00:20","narration":"Noura is writing an Animal Fact Card about the green sea turtle!","on_screen":"My Animal Fact Card","visual":"Noura at a library table with an ocean book and a notebook."},{"time":"00:20–00:55","narration":"Research: find three facts and write the source. Plan: Hamburger!","on_screen":"1 Research + Plan 🔍🍔","visual":"Sticky notes with facts fly from the book onto a hamburger organizer."},{"time":"00:55–01:50","narration":"Draft: The green sea turtle is made for life in the warm Red Sea. First, it has strong flippers…","on_screen":"2 Draft – topic + 3 details + closing","visual":"Each sentence appears with linking words in coral."},{"time":"01:50–02:20","narration":"Revise: Is every detail about the turtle? Add an explaining sentence!","on_screen":"3 Revise ➕ explain","visual":"A partner points to a detail; Noura adds a thin 'explain' layer."},{"time":"02:20–02:40","narration":"Edit: commas after linking words, has/have, its, periods – check!","on_screen":"4 Edit , has/have its .","visual":"Commas pop into place; 'have' changes to 'has'."},{"time":"02:40–03:00","narration":"Publish: Noura's Animal Fact Card goes on the class 'Wild Wall'!","on_screen":"5 Publish 🐢","visual":"A wall of animal fact cards with drawings and habitat labels."}],"captions_ar":["نورة تكتب بطاقة حقائق عن السلحفاة البحرية الخضراء!","البحث: جِد ثلاث حقائق واكتب المصدر. التخطيط: خطة الهامبرغر!","المسودة: السلحفاة الخضراء مهيأة للحياة في البحر الأحمر الدافئ. أولًا: لها زعانف قوية…","التحسين: هل كل تفصيل عن السلحفاة؟ أضف جملة شارحة!","التدقيق: الفواصل بعد كلمات الربط، وhas/have، وits، والنقاط.","النشر: بطاقة نورة على «جدار البرية» في الفصل!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Noura (the Writer) reads her paragraph clearly."},"texts":[],"activities":[{"id":"RW-L03-U1-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Which is the best topic sentence for an Animal Fact Card?","answer":"The Arabian oryx is made for life in the desert.","explanation":"Animal + habitat + main idea.","explanation_ar":"جملة رئيسية مناسبة.","options":["I went to the zoo.","Animals.","My favorite color is blue.","The Arabian oryx is made for life in the desert."],"dok":1,"skill":"topic sentence","stage":"controlled"},{"q":"Which sentence about sea turtles is a FACT?","answer":"Sea turtles lay eggs on the beach.","explanation":"A fact can be checked.","explanation_ar":"حقيقة.","options":["Sea turtles lay eggs on the beach.","Sea turtles are the cutest animals.","I think turtles are boring.","Turtles are my favorite."],"dok":1,"skill":"fact vs. opinion","stage":"controlled"},{"q":"Where do you write where your facts came from?","answer":"in the source line","explanation":"Source = where you got information.","explanation_ar":"سطر المصدر.","options":["in the topic sentence","in the source line","in the title only","nowhere"],"dok":1,"skill":"research","stage":"controlled"},{"q":"A colorful underwater place made by tiny sea animals is a ___.","answer":"coral reef","explanation":"Coral reef.","explanation_ar":"شعاب مرجانية.","options":["burrow","coral reef","desert","nest"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"*Green turtles eat seagrass.* What is seagrass?","answer":"a green plant that grows under the sea","explanation":"Sea + grass.","explanation_ar":"عشب بحري.","options":["a green plant that grows under the sea","a kind of fish","a turtle's shell","sand on the beach"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which detail about the oryx has the comma in the right place?","answer":"In addition, the oryx can smell rain from far away.","explanation":"Comma after In addition.","explanation_ar":"الفاصلة بعد In addition.","options":["In addition the oryx, can smell rain.","In, addition the oryx can smell rain.","In addition, the oryx can smell rain from far away.","In addition the oryx can smell, rain."],"dok":2,"skill":"punctuation","stage":"controlled"}]},{"id":"RW-L03-U1-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the paragraph or sentence in order.","instructions_ar":"رتّب الفقرة أو الجملة.","items":[{"q":"Order the oryx paragraph.","answer":"The Arabian oryx is made for life in the desert. → First, its white coat reflects the hot sun. → Also, it can go for weeks without drinking water. → In addition, its wide hooves help it walk on sand. → For all these reasons, the oryx survives in the desert.","explanation":"Topic → 3 details → closing.","explanation_ar":"رئيسية ← تفاصيل ← خاتمة.","stage":"guided","parts":["For all these reasons, the oryx survives in the desert.","Also, it can go for weeks without drinking water.","The Arabian oryx is made for life in the desert.","In addition, its wide hooves help it walk on sand.","First, its white coat reflects the hot sun."],"target":["The Arabian oryx is made for life in the desert.","First, its white coat reflects the hot sun.","Also, it can go for weeks without drinking water.","In addition, its wide hooves help it walk on sand.","For all these reasons, the oryx survives in the desert."]},{"q":"Build detail 1 for a sea turtle.","answer":"First, it has strong flippers for swimming.","explanation":"Linking word + detail.","explanation_ar":"رابط + تفصيل.","stage":"guided","parts":["strong flippers","First,","it has","for swimming."],"target":["First,","it has","strong flippers","for swimming."]},{"q":"Build a shell detail.","answer":"Its hard shell → protects it → from sharks.","explanation":"Detail sentence.","explanation_ar":"جملة تفصيل.","stage":"guided","parts":["protects it","from sharks.","Its hard shell"],"target":["Its hard shell","protects it","from sharks."]},{"q":"Build an explaining sentence about seagrass.","answer":"This food gives it energy.","explanation":"Explaining sentence.","explanation_ar":"جملة شارحة.","stage":"guided","parts":["gives it","This food","energy."],"target":["This food","gives it","energy."]},{"q":"Build a source line.","answer":"Source: → \"Ocean Animals,\" → school library book","explanation":"Source line.","explanation_ar":"سطر المصدر.","stage":"guided","parts":["Source:","school library book","\"Ocean Animals,\""],"target":["Source:","\"Ocean Animals,\"","school library book"]},{"q":"Build a topic sentence about a woodpecker.","answer":"The woodpecker → is made for life → in the forest.","explanation":"Topic sentence.","explanation_ar":"جملة رئيسية.","stage":"guided","parts":["is made for life","in the forest.","The woodpecker"],"target":["The woodpecker","is made for life","in the forest."]}]},{"id":"RW-L03-U1-LS5-A3","type":"organizer","stage":"freer","instructions":"Organizer: Plan your Animal Fact Card.","instructions_ar":"خطط لبطاقة حقائق حيوانك.","items":[{"q":"Which animal and habitat did you choose? Write your topic sentence.","answer":"The fennec fox is made for life in the Sahara Desert.","explanation":"Animal + habitat.","explanation_ar":"حيوان + بيئة.","dok":1,"skill":"planning","stage":"freer"},{"q":"Write notes for three key facts in your own words.","answer":"giant ears – hear prey, lose heat; sandy fur – hides it; burrow – cool in the day","explanation":"Three notes.","explanation_ar":"ثلاث ملاحظات.","dok":2,"skill":"research","stage":"freer"},{"q":"Write one explaining note for a fact.","answer":"Giant ears let heat out, so the fox stays cool.","explanation":"Explain a fact.","explanation_ar":"اشرح حقيقة.","dok":2,"skill":"planning","stage":"freer"},{"q":"Write your closing and your source.","answer":"For all these reasons, the fennec fox is a small desert survivor. Source: Animal fact card 7.","explanation":"Closing + source.","explanation_ar":"خاتمة + مصدر.","dok":2,"skill":"planning","stage":"freer"}]},{"id":"RW-L03-U1-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write, revise, edit and publish your paragraph.","instructions_ar":"اكتب فقرتك وحسّنها ودققها وانشرها.","items":[{"q":"Write your topic sentence and your first detail with an explaining sentence.","answer":"The green sea turtle is made for life in the warm Red Sea. First, it has strong flippers that help it swim long distances. It can swim hundreds of kilometers to find food.","explanation":"Topic + detail + explain.","explanation_ar":"رئيسية + تفصيل + شرح.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your second and third details with Also and In addition.","answer":"Also, its hard shell protects it from sharks. In addition, it eats seagrass, a green plant that grows under the sea.","explanation":"Two linked details.","explanation_ar":"تفصيلان مربوطان.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your closing sentence and source line.","answer":"For all these reasons, the green sea turtle can survive in its ocean habitat. Source: \"Ocean Animals.\"","explanation":"Closing + source.","explanation_ar":"خاتمة + مصدر.","dok":2,"skill":"writing","stage":"production"},{"q":"What did your partner suggest? What did you change?","answer":"My partner said my second detail was about dolphins, so I changed it to a fact about the turtle's shell.","explanation":"Revision note.","explanation_ar":"ملاحظة التحسين.","dok":3,"skill":"revising","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L03-U1-LS5-ORG","type":"organizer","organizer":"Hamburger Plan","instructions":"Organizer: Write your topic sentence on the top bun, one key detail and an explaining note on each layer, and your closing on the bottom bun. Add your source.","items":[{"q":"Top bun – topic sentence (animal + habitat)","answer":"The green sea turtle is made for life in the warm Red Sea."},{"q":"Layer 1 – key detail + explain","answer":"strong flippers – swim long distances to find food"},{"q":"Layer 2 – key detail + explain","answer":"hard shell – protects it from sharks"},{"q":"Layer 3 – key detail + explain","answer":"eats seagrass – gives energy"},{"q":"Bottom bun – closing (new words)","answer":"For all these reasons, the green sea turtle can survive in its ocean habitat."},{"q":"Source","answer":"\"Ocean Animals\" (school library book)"}]},{"id":"RW-L03-U1-LS5-WR","type":"writing","instructions":"Writing: Write an informative paragraph (6–8 sentences) about one animal and its habitat. Include a topic sentence, three key details with linking words, a closing sentence and your source. Write an informative paragraph (6–8 sentences) about one animal and its habitat. Include a topic sentence, three key details with linking words, a closing sentence and your source.","instructions_ar":"اكتب فقرة معلوماتية (6–8 جمل) عن حيوان واحد وبيئته، فيها جملة رئيسية وثلاثة تفاصيل رئيسية بكلمات الربط وجملة ختامية والمصدر.","prompt":"Write an informative paragraph (6–8 sentences) about one animal and its habitat. Include a topic sentence, three key details with linking words, a closing sentence and your source.","checklist":["My topic sentence names the animal and its habitat.","I wrote three key details that are facts.","I added at least one explaining sentence.","I used First, Also and In addition (with commas).","I used at least three unit words (habitat, survive, protect…).","My closing sentence says the main idea in new words.","I checked has/have, its/it's and periods; I wrote my source."],"rubric_id":"RW-RUBRIC-5T","min_words":70,"max_words":140,"organizer":"Hamburger Plan (topic sentence – 3 details + explanations – closing – source)","items":[{"q":"Write an informative paragraph (6–8 sentences) about one animal and its habitat. Include a topic sentence, three key details with linking words, a closing sentence and your source.","answer":"The green sea turtle is made for life in the warm Red Sea. First, it has strong flippers, or flat arms, that help it swim long distances. It can swim hundreds of kilometers to find food. Also, its hard shell protects it from sharks. In addition, it eats seagrass, a green plant that grows under the sea. This food gives it the energy to keep swimming. For all these reasons, the green sea turtle can survive in its ocean habitat. (Source: \"Ocean Animals,\" school library book)","_w":{"checklist":["My topic sentence names the animal and its habitat.","I wrote three key details that are facts.","I added at least one explaining sentence.","I used First, Also and In addition (with commas).","I used at least three unit words (habitat, survive, protect…).","My closing sentence says the main idea in new words.","I checked has/have, its/it's and periods; I wrote my source."],"min":70,"max":140}}]}],"game":{"name":"Fact or Opinion Safari","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Safari sort: sentence cards appear on animals walking across the screen; the child taps 'Fact' or 'Opinion'. Correct facts are added to a fact card that builds itself.","Teams take turns picking a sentence card.","The team decides: FACT (can be checked) or OPINION (what someone thinks).","Facts that fit the team's animal go on its fact card.","Each correct sort = 1 point; a fact used in the paragraph = 2 points.","The team with the most points leads the class safari."],"data":[]},"exit_quiz":[{"q":"An informative paragraph gives the reader ___.","answer":"facts","explanation":"Informative = facts.","explanation_ar":"حقائق.","options":["a story with a problem","a poem with rhyme","facts","only opinions"],"dok":1,"skill":"genre"},{"q":"Before you write an informative paragraph, you should ___.","answer":"research and take notes","explanation":"Research first.","explanation_ar":"البحث وتدوين الملاحظات.","options":["draw the closing","research and take notes","copy a whole page","skip the plan"],"dok":1,"skill":"research"},{"q":"Which sentence is an OPINION?","answer":"Owls are the most beautiful birds.","explanation":"It tells what someone thinks.","explanation_ar":"رأي.","options":["Owls hunt at night.","Owls have sharp claws.","Owls build nests in tree holes.","Owls are the most beautiful birds."],"dok":1,"skill":"fact vs. opinion"},{"q":"*Write the source of your facts.* A source is ___.","answer":"where you got the information","explanation":"Source = where information comes from.","explanation_ar":"مصدر.","options":["the last sentence","where you got the information","a kind of animal","a linking word"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence about a turtle shows correct subject–verb agreement?","answer":"The turtle has a hard shell.","explanation":"One turtle → has.","explanation_ar":"has.","options":["The turtle have a hard shell.","The turtles has a hard shell.","The turtle has a hard shell.","The turtle having a hard shell."],"dok":2,"skill":"grammar"},{"q":"Topic sentence: *The dolphin is made for life in the ocean.* Which detail belongs?","answer":"Dolphins breathe air through a hole on top of their heads.","explanation":"About dolphins in the ocean.","explanation_ar":"ينتمي.","options":["Dolphins breathe air through a hole on top of their heads.","Camels store fat.","Foxes dig burrows.","Owls see in the dark."],"dok":2,"skill":"relevant details"},{"q":"Why should you write facts in your own words?","answer":"Copying is not your own writing, and your words show you understand.","explanation":"Own words = understanding.","explanation_ar":"لتُظهر فهمك ولا تنسخ.","options":["Your own words are always shorter.","Books are wrong.","Teachers like long words.","Copying is not your own writing, and your words show you understand."],"dok":2,"skill":"research skills"},{"q":"Which closing sentence is best for an oryx paragraph?","answer":"For all these reasons, the oryx is a true desert survivor.","explanation":"New words + main idea.","explanation_ar":"خاتمة مناسبة.","options":["The Arabian oryx is made for life in the desert.","First, its coat is white.","I like oryxes.","For all these reasons, the oryx is a true desert survivor."],"dok":2,"skill":"closing"},{"q":"Which revision makes a paragraph STRONGER?","answer":"adding an explaining sentence to a detail","explanation":"Explanations strengthen details.","explanation_ar":"إضافة جملة شارحة.","options":["adding an explaining sentence to a detail","adding a detail about a different animal","removing the topic sentence","adding three opinions"],"dok":3,"skill":"revising"},{"q":"Which Animal Fact Card is the most complete?","answer":"topic sentence, three facts with linking words, an explaining sentence, a closing and a source","explanation":"It has every part.","explanation_ar":"الأكثر اكتمالًا.","options":["topic sentence, three facts with linking words, an explaining sentence, a closing and a source","a drawing and the animal's name","three opinions about the animal","one fact and no closing"],"dok":3,"skill":"evaluate"}],"images":[{"id":"IMG-RW-L03-U1-LS5-V01","prompt":"Picture for the word 'informative': a book with a light-bulb icon"},{"id":"IMG-RW-L03-U1-LS5-V02","prompt":"Picture for the word 'fact': a checkmark next to a sentence"},{"id":"IMG-RW-L03-U1-LS5-V03","prompt":"Picture for the word 'research': a child reading a non-fiction book with notes"},{"id":"IMG-RW-L03-U1-LS5-V04","prompt":"Picture for the word 'coral reef': a colorful Red Sea coral reef"},{"id":"IMG-RW-L03-U1-LS5-V05","prompt":"Picture for the word 'lay eggs': a turtle laying eggs in a sandy hole"},{"id":"IMG-RW-L03-U1-LS5-V06","prompt":"Picture for the word 'seagrass': a turtle grazing on seagrass"},{"id":"IMG-RW-L03-U1-LS5-V07","prompt":"Picture for the word 'source': a book, a tablet and a teacher icon"},{"id":"IMG-RW-L03-U1-LS5-01","prompt":"Noura's fact card about the green sea turtle on the class wall."},{"id":"IMG-RW-L03-U1-LS5-02","prompt":"Research notes on sticky notes next to a library book."},{"id":"IMG-RW-L03-U1-LS5-03","prompt":"A classroom wall with animal fact cards in three habitats."}],"audio":[{"id":"AUD-RW-L03-U1-LS5-V01","script":"informative. An informative paragraph teaches the reader facts."},{"id":"AUD-RW-L03-U1-LS5-V02","script":"fact. It is a fact that turtles have shells."},{"id":"AUD-RW-L03-U1-LS5-V03","script":"research. I research my animal in the library."},{"id":"AUD-RW-L03-U1-LS5-V04","script":"coral reef. Many fish live on the coral reef."},{"id":"AUD-RW-L03-U1-LS5-V05","script":"lay eggs. Turtles lay eggs on the beach."},{"id":"AUD-RW-L03-U1-LS5-V06","script":"seagrass. Green turtles eat seagrass."},{"id":"AUD-RW-L03-U1-LS5-V07","script":"source. Write the source of your facts."},{"id":"AUD-RW-L03-U1-LS5-VID","script":"Noura is writing an Animal Fact Card about the green sea turtle! Research: find three facts and write the source. Plan: Hamburger! Draft: The green sea turtle is made for life in the warm Red Sea. First, it has strong flippers… Revise: Is every detail about the turtle? Add an explaining sentence! Edit: commas after linking words, has/have, its, periods – check! Publish: Noura's Animal Fact Card goes on the class 'Wild Wall'!"}]}],"unit_test":[{"q":"Which word means *the natural home of an animal or plant*?","answer":"habitat","explanation":"Habitat = natural home.","explanation_ar":"موطن.","options":["feathers","habitat","claws","survive"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Rabbits dig a ___ to sleep under the ground.","answer":"burrow","explanation":"Under the ground = burrow.","explanation_ar":"جُحرًا.","options":["nest","burrow","shell","coral reef"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"An eagle grabs fish with its sharp ___.","answer":"claws","explanation":"Sharp nails = claws.","explanation_ar":"مخالب.","options":["fur","flippers","shell","claws"],"dok":1,"skill":"body parts","_part":"Part A – Vocabulary"},{"q":"Polar bears have thick white ___ that keeps them warm.","answer":"fur","explanation":"Hair on mammals = fur.","explanation_ar":"فرو.","options":["feathers","shells","fur","claws"],"dok":1,"skill":"body parts","_part":"Part A – Vocabulary"},{"q":"Mother birds sit on their eggs to ___ them from the cold.","answer":"protect","explanation":"Keep safe = protect.","explanation_ar":"تحمي.","options":["hunt","sink","store","protect"],"dok":1,"skill":"vocabulary in context","_part":"Part A – Vocabulary"},{"q":"*Some lizards change color to **blend in**, or look like the things around them.* What does *blend in* mean?","answer":"look like the things around them","explanation":"Signal: or.","explanation_ar":"يندمج مع ما حوله.","options":["look like the things around them","run very fast","lose their tails","lay eggs"],"dok":2,"skill":"definition clues","_part":"Part A – Vocabulary"},{"q":"*Bears **hibernate**, which means they sleep through the whole winter.* What does *hibernate* mean?","answer":"sleep through the whole winter","explanation":"Signal: which means.","explanation_ar":"يُسبت.","options":["sleep through the whole winter","hunt in the ocean","climb trees","build nests"],"dok":2,"skill":"definition clues","_part":"Part A – Vocabulary"},{"q":"Which sentence uses *survive* correctly?","answer":"Cactus plants can survive with very little water.","explanation":"Survive = stay alive.","explanation_ar":"استخدام صحيح.","options":["I survive my homework to the teacher.","The cat survives the ball to me.","Cactus plants can survive with very little water.","We survive dinner at seven."],"dok":2,"skill":"usage","_part":"Part A – Vocabulary"},{"q":"Details: *Penguins swim fast. They have blubber. They live in colonies.* Which topic sentence fits?","answer":"Penguins have many ways to survive in the cold.","explanation":"It covers all the details.","explanation_ar":"تناسب كل التفاصيل.","options":["Penguins are black and white.","Penguins have many ways to survive in the cold.","I want a pet penguin.","Fish live in the sea."],"dok":2,"skill":"topic sentence","_part":"Part D – Paragraph skills"},{"q":"Topic sentence: *Camels are made for the desert.* Which detail does NOT belong?","answer":"Penguins live near Antarctica.","explanation":"Penguins are not about camels.","explanation_ar":"لا ينتمي.","options":["Camels store fat in their humps.","Camels have long eyelashes.","Camels have wide feet.","Penguins live near Antarctica."],"dok":1,"skill":"relevant details","_part":"Part D – Paragraph skills"},{"q":"Which detail about penguins has the comma in the right place?","answer":"In addition, penguins live in big colonies.","explanation":"Comma after In addition.","explanation_ar":"الفاصلة بعد In addition.","options":["In addition penguins, live in big colonies.","In addition, penguins live in big colonies.","In addition penguins live, in big colonies.","In, addition penguins live in big colonies."],"dok":1,"skill":"punctuation","_part":"Part D – Paragraph skills"},{"q":"Which sentence about penguins is an OPINION?","answer":"Penguins are the funniest birds in the world.","explanation":"It tells what someone thinks.","explanation_ar":"رأي.","options":["Penguins cannot fly.","Penguins eat fish.","Penguins are the funniest birds in the world.","Penguins have blubber."],"dok":1,"skill":"fact vs. opinion","_part":"Part D – Paragraph skills"},{"q":"Which closing sentence is best for a penguin paragraph?","answer":"For all these reasons, penguins are true survivors of the icy south.","explanation":"New words + main idea.","explanation_ar":"خاتمة مناسبة.","options":["For all these reasons, penguins are true survivors of the icy south.","Penguins have many ways to survive in the cold.","First, penguins swim fast.","Do you like penguins?"],"dok":2,"skill":"closing","_part":"Part D – Paragraph skills"},{"q":"Which sentence about the penguin's body is correct?","answer":"The penguin has a thick layer of fat.","explanation":"One penguin → has.","explanation_ar":"has.","options":["The penguin have a thick layer of fat.","The penguins has a thick layer of fat.","The penguin has a thick layer of fat.","The penguin having a thick layer of fat."],"dok":2,"skill":"grammar","_part":"Part D – Paragraph skills"}],"unit_writing":{"task":"Choose ONE animal from this test (the penguin or a bird in a tree) or from the unit. Write an informative paragraph with a topic sentence, three key details with linking words and a closing sentence.","model":"Penguins are birds that are made for life in the cold south. First, their wings work like flippers, so they can swim fast to catch fish. Also, a thick layer of fat called blubber keeps them warm in icy water. In addition, they live in big groups called colonies and stand close together to share warmth. These habits help them stay alive in very cold weather. For all these reasons, penguins are amazing survivors even though they cannot fly.","marks":20}});
